  /**
   * v0.3.1 (runtime truth contract §五): the per-runId task-graph store. Use this
   * for new code; getTaskGraph() returns the legacy default-run shim.
   */
  getTaskGraphStore(): TaskGraphStore {
    return this.taskGraphStore
  }

  getBackgroundTaskManager(): BackgroundTaskManager {
    return this.backgroundTaskManager
  }

  getProviderCircuitState(): ReturnType<RuntimeCoordinator['getProviderCircuitState']> {
    return this.coordinator.getProviderCircuitState()
  }

  restoreProviderCircuitState(
    state: Parameters<RuntimeCoordinator['restoreProviderCircuitState']>[0],
