  getPermissionManager(): PermissionManager {
    return this.permissionManager
  }

  getEventLog(): EngineConfig['eventLog'] {
    return this.eventLog
  }

  isPlanMode(): boolean {
    return this.sharedState.planModeActive
  }

  getConfig(): EngineConfig {
    return this.config
  }

  /**
   * runtime invariants P0-1: the ExecutionRun registry is ALWAYS present.
   * (Previously returned undefined when persistence was off — that
   * broke any caller that wanted to mint child runs without
   * configuring a log directory.)
   */
  getRunRegistry(): ExecutionRunRegistry {
    return this.runRegistry
  }

  /**
   * The ExecutionRun event bus. Always present; subscribers receive
   * every run/tool/artifact/verification event with persist-first
   * ordering (when an EventStore is wired in).
   */
  getRunEventBus(): ExecutionRunEventBus {
    return this.runEventBus
  }

  exitPlanMode(): void {
    this.sharedState.planModeActive = false
  }

  enterPlanMode(): void {
    this.sharedState.planModeActive = true
  }

  queueSnip(keepRecent: number): void {
    this.contextManager.queueSnip(keepRecent)
  }

  getFileHistory(): FileHistory | null {
    return this.fileHistory
  }

  getToolRegistry(): ToolRegistry {
    return this.toolRegistry
  }

  getEventEmitter(): RunEventEmitter {
    return this.eventEmitter
  }

  getSharedState(): SharedRuntimeState {
    return this.sharedState
  }

  /**
   * Returns the base tool list constructed by createTools. These are
   * the same Tool instances wired into the ToolRegistry. Useful for
   * integration tests that need to inspect per-tool wiring (e.g.
   * verify AgentTool.runRegistry was set by the Engine constructor).
   */
  getTools(): Tool[] {
    return this.tools
  }

  /**
   * Returns the ToolScheduler instance used by the coordinator.
   * Integration tests inspect its deps to verify ResourceScheduler
   * wiring.
   */
  getToolScheduler(): ToolScheduler {
    return this.toolScheduler
  }

  /**
   * Returns the ResourceScheduler. Always present (runtime invariants P1-1).
   */
  getResourceScheduler(): ResourceScheduler {
    return this.resourceScheduler
  }
}

/**
 * McpHttpClient — minimal HTTP transport for MCP servers (with OAuth).
 *
 * Implements just enough of the MCP spec to connect to an HTTP server
 * (with optional OAuth bearer token), list its tools, and invoke them.
 * Transport is JSON-RPC 2.0 over HTTP POST.
 *
 * Scope (v1): HTTP transport + tools protocol. NOT implemented: SSE
 * streaming, sampling, resources/prompts protocols.
 */

import type { McpServerConfig, McpToolInfo } from './mcpClient.js'
import { getValidToken } from '../integrations/mcpOAuth.js'

export interface McpHttpClientOptions {
  /** Override the fetch implementation (for tests). */
  fetchImpl?: typeof fetch
}

interface JsonRpcRequest {
  jsonrpc: '2.0'
  id: number | string
  method: string
  params?: Record<string, unknown>
}

interface JsonRpcResponse<T = unknown> {
  jsonrpc: '2.0'
  id?: number | string
  result?: T
  error?: { code: number; message: string; data?: unknown }
}

export class McpHttpClient {
  private nextId = 1
  private connected = false

  constructor(
    private readonly server: McpServerConfig,
    private readonly opts: McpHttpClientOptions = {},
  ) {}

  get isConnected(): boolean {
    return this.connected
  }

  async connect(): Promise<void> {
    if (this.server.type !== 'http') {
      throw new Error(`McpHttpClient cannot connect to non-http server "${this.server.name}"`)
    }
    if (!this.server.url) {
      throw new Error(`McpHttpClient: server "${this.server.name}" missing url`)
    }
    this.connected = true
  }

  private getFetch(): typeof fetch {
    return this.opts.fetchImpl ?? fetch
  }

  private getHeaders(): Record<string, string> {
    const headers: Record<string, string> = {
      'content-type': 'application/json',
      accept: 'application/json',
    }
    if (this.server.headers) {
      for (const [k, v] of Object.entries(this.server.headers)) {
        headers[k] = v
      }
    }
    return headers
  }

  private async getAuthHeader(): Promise<Record<string, string>> {
    if (!this.server.oauth) return {}
    if (!this.server.oauth.clientId || !this.server.oauth.tokenEndpoint) {
      return {}
    }
    try {
      const token = await getValidToken(this.server.name, {
        serverId: this.server.name,
        authorizationEndpoint: this.server.oauth.authorizationEndpoint,
        tokenEndpoint: this.server.oauth.tokenEndpoint,
        clientId: this.server.oauth.clientId,
        clientSecret: this.server.oauth.clientSecret,
        scope: this.server.oauth.scope,
        redirectUri: this.server.oauth.redirectUri,
      }, this.getFetch())
      return { authorization: `Bearer ${token}` }
    } catch (err) {
      throw new Error(
        `MCP OAuth for "${this.server.name}" failed: ${(err as Error).message}. ` +
        'Run `ovolv999 mcp auth ' + this.server.name + '` to authorize.',
      )
    }
  }

  private async call<T>(method: string, params?: Record<string, unknown>): Promise<T> {
    if (!this.connected || !this.server.url) {
      throw new Error(`McpHttpClient "${this.server.name}" not connected`)
    }
    const body: JsonRpcRequest = {
      jsonrpc: '2.0',
      id: this.nextId++,
      method,
      params,
    }
    const authHeader = await this.getAuthHeader()
    const headers = { ...this.getHeaders(), ...authHeader }
    const response = await this.getFetch()(this.server.url, {
      method: 'POST',
      headers,
      body: JSON.stringify(body),
    })
    if (!response.ok) {
      throw new Error(
        `MCP HTTP ${this.server.name} ${method} failed: ${response.status} ${response.statusText}`,
      )
    }
    const json = (await response.json()) as JsonRpcResponse<T>
    if (json.error) {
      throw new Error(`MCP HTTP ${this.server.name} ${method}: ${json.error.message}`)
    }
    return json.result as T
  }

  async listTools(): Promise<McpToolInfo[]> {
    const result = await this.call<{ tools: McpToolInfo[] }>('tools/list', {})
    return result.tools
  }

  async callTool(name: string, args: Record<string, unknown>): Promise<unknown> {
    const result = await this.call<{ content: unknown; isError?: boolean }>(
      'tools/call',
      { name, arguments: args },
    )
    return result
  }

  async close(): Promise<void> {
    this.connected = false
  }
}

/**
 * MemoryCandidate + MemoryPromoter — Candidate → Promotion lifecycle.
 *
 * v0.5.3 Final (task 2):
 *
 *   memory_write  →  creates a MemoryCandidate on the run-scoped context.
 *   Run completes  →  MemoryPromoter reads the verdict and promotes or
 *                     drops each candidate.
 *
 * Anti-fake-success invariants this design enforces:
 *
 *   1. NO semantic write happens during tool execution. The model can
 *      only INJECT a claim; the engine decides whether to persist it.
 *   2. user_stated is NOT trusted from the model's `source` field.
 *      A user-stated candidate must carry `sourceQuote`; the engine
 *      verifies the quote is a normalized contiguous substring of the
 *      original user message. Without that, the candidate is
 *      demoted to `agent_inferred`.
 *   3. Promotion to verified=true only happens when the run's
 *      CompletionContract verdict is `completed` AND Reviewer passed
 *      AND verification.executed === passed === no-failed.
 *   4. Any other outcome promotes to `kind: failure, verified: false`.
 *      Failure entries never enter the success-memory read pool.
 *
 * Storage:
 *   The candidates live on the per-run `RunScopedRuntimeContext`. They
 *   are NOT in a global singleton. Per-run storage means a re-run
 *   does not leak candidates from the previous run, and the promoter
 *   reads only the candidates created by THIS runId.
 */

import { createHash, randomUUID } from 'crypto'
import type { CompletionStatus, TurnOutcome } from './runtime/turnOutcome.js'
import type { MemoryRecord, MemoryKind } from './longTermMemory.js'

// ── Candidate shape ─────────────────────────────────────────────────────

/**
 * What the model claims about a fact's source. Treated as
 * untrusted metadata only; the engine validates user_stated via
 * sourceQuote and demotes to agent_inferred on failure.
 */
export type ClaimedMemorySource =
  | 'user_stated'
  | 'agent_inferred'
  | 'tool_observed'

export interface MemoryCandidate {
  id: string
  runId: string
  /** Resolved via RevisionBinding — populated at promotion time, not at
   *  candidate-creation time (we don't know it yet). */
  repo?: string
  content: string
  claimedSource: ClaimedMemorySource
  /** Engine-verified quote proving the model saw the user say this.
   *  Required iff claimedSource === 'user_stated'. */
  sourceQuote?: string
  tags: string[]
  confidence: number
  createdAt: string
  /**
   * Set after the user-message verifier runs. 'promote' → candidate
   * enters the promotion queue; 'demote-agent_inferred' → the
   * candidate is treated as agent_inferred (its claimedSource is
   * overridden). 'unverified' → we cannot confirm or deny; treated
   * as agent_inferred for safety.
   */
  userSourceVerification?: 'promote' | 'demote-agent_inferred' | 'unverified'
  /**
   * v0.5.3 Hotfix §2 — Claim-Level Evidence. Promotion only
   * succeeds when at least one of:
   *   - claimedSource === 'user_stated' AND userSourceVerification === 'promote'
   *   - claimedSource === 'tool_observed' AND a tool_result
   *     evidence ref verifies against a real ToolResult in the run
   *   - an explicit verification evidence ref points at a known
   *     EvidenceStore id
   *   - a file evidence ref points at a real on-disk file
   * Candidates without any evidence that resolves to verified=true
   * are either dropped (during a successful run) or saved as
   * kind='reflection', verified=false (audit trail).
   */
  evidenceRefs?: MemoryEvidenceRef[]
}

/**
 * v0.5.3 Hotfix §2 — A single piece of claim-level evidence
 * backing a MemoryCandidate. Promotion examines each ref and
 * either resolves it (verified) or rejects the candidate.
 */
export type MemoryEvidenceRef =
  | {
      kind: 'user_quote'
      quote: string
    }
  | {
      kind: 'tool_result'
      toolCallId: string
      resultQuote: string
    }
  | {
      kind: 'file'
      path: string
      contentHash?: string
    }
  | {
      kind: 'verification'
      evidenceId: string
    }

// ── RevisionBinding ─────────────────────────────────────────────────────

/**
 * v0.5.3 Final (task 3): every persisted memory record binds to a
 * real revision state. Either git branch + HEAD (clean repo), git
 * baseCommit + diffHash (dirty), or non-git absolute cwd +
 * workspaceHash. NO `repo=memory|reflection|session` and NO
 * `sourceRunId=unknown`.
 */
export interface RevisionBinding {
  /** Repo URL or absolute path. Required, derived from EngineConfig.cwd. */
  repo: string
  /** Git branch when present and clean. */
  branch?: string
  /** HEAD commit when clean, or last clean commit when dirty. */
  baseCommit?: string
  /** True iff the working tree has uncommitted changes. */
  dirty: boolean
  /** Stable hash of the dirty diff (sha256 of git diff output). */
  diffHash?: string
  /** For non-Git paths, sha256(cwd + mtime of files). */
  workspaceHash?: string
}

// ── Normalized-contiguous substring match ───────────────────────────────

/**
 * Normalize whitespace + case-fold for the purpose of quote
 * verification. Strips all whitespace and CJK punctuation marks
 * used as filler, then lowercases.
 */
function normalize(s: string): string {
  return s
    .toLowerCase()
    .replace(/[\s  ]+/g, '')
    // Strip CJK speech marks + quote glyphs that fluctuate in chat.
    .replace(/[“”‘’＂＇、。]/g, '')
}

/**
 * True iff `quote` is a contiguous (after normalization) substring
 * of `userMessage`. Returns true also when both are empty (vacuously
 * true) — but the promoter denies empty quotes anyway.
 */
export function isNormalizedSubstring(quote: string, userMessage: string): boolean {
  if (!quote) return false
  return normalize(userMessage).includes(normalize(quote))
}

/**
 * v0.5.3 Final (P1): minimum normalized quote length. A 1–2 char
 * quote (e.g. `"用"`, `"the"`, `",,"`) would otherwise pass the
 * `isNormalizedSubstring` check and let the model attribute any
 * claim to the user. We refuse those outright.
 */
export const MIN_USER_STATED_QUOTE_NORM_LENGTH = 12

/**
 * v0.5.3 Final (P1): minimum fraction of content tokens that must
 * already appear (as substrings) in the normalized quote. Without
 * this check a model can write a free-form `content` and append a
 * 1-char quote to launder it as a user preference. We require the
 * content to be DERIVABLE from the quote's vocabulary.
 */
export const MIN_CONTENT_TOKEN_COVERAGE = 0.6

/**
 * v0.5.3 Final (P1): result of verifying a source quote against
 * the original user message. Replaces the previous single-bit
 * `isNormalizedSubstring` with a multi-factor verification:
 *
 *   - 'verified'                  → claim accepted, origin = user_prompt
 *   - 'demote-agent_inferred'     → drop the user_stated claim; treat as inferred
 *   - 'drop'                      → drop both the user_stated claim and the candidate itself
 */
export type SourceVerification =
  | { result: 'verified' }
  | { result: 'demote-agent_inferred'; reason: string }
  | { result: 'drop'; reason: string }

/**
 * Multi-factor verification of a user_stated memory candidate's
 * source_quote. Returns the decision the promoter should apply.
 * The function is pure — it does not write anywhere.
 */
export function verifySourceQuote(opts: {
  sourceQuote: string | undefined
  userMessage: string
  content: string
}): SourceVerification {
  const quote = (opts.sourceQuote ?? '').trim()
  if (!quote) {
    return { result: 'drop', reason: 'user_stated missing sourceQuote' }
  }
  const normalized = normalize(quote)
  if (normalized.length < MIN_USER_STATED_QUOTE_NORM_LENGTH) {
    return {
      result: 'drop',
      reason: `sourceQuote too short (${normalized.length} < ${MIN_USER_STATED_QUOTE_NORM_LENGTH})`,
    }
  }
  if (!isNormalizedSubstring(quote, opts.userMessage)) {
    // v0.5.3 Hotfix §2: user_stated validation FAILURE is now
    // an unconditional DROP. The previous behaviour demoted to
    // agent_inferred and the candidate could still be promoted
    // (as a successful semantic record). A forged quote
    // therefore gave a free pass. Drop closes the loophole.
    return {
      result: 'drop',
      reason: 'sourceQuote not a substring of userMessage',
    }
  }
  // Coverage: how much of `content` derives from `quote`?
  const coverage = computeContentTokenCoverage(opts.content, quote)
  if (coverage < MIN_CONTENT_TOKEN_COVERAGE) {
    return {
      result: 'drop',
      reason: `content coverage of quote ${coverage.toFixed(2)} < ${MIN_CONTENT_TOKEN_COVERAGE}`,
    }
  }
  return { result: 'verified' }
}

/**
 * Fraction of content tokens (size ≥ 3, alnum) that already appear
 * inside the normalized quote. CJK + Latin are handled with a
 * mixed tokenization (length-3+ alnum; length-2 bigrams for CJK).
 */
export function computeContentTokenCoverage(content: string, quote: string): number {
  const tokens = extractClaimTokens(content)
  if (tokens.length === 0) return 1 // no tokens → trivially covered
  const normalizedQuote = normalize(quote)
  let hits = 0
  for (const tok of tokens) {
    if (normalizedQuote.includes(tok)) hits++
  }
  return hits / tokens.length
}

function extractClaimTokens(content: string): string[] {
  const out: string[] = []
  // Latin alphanumeric tokens of length ≥ 3.
  const latin = content.toLowerCase().match(/[a-z0-9]{3,}/g) ?? []
  for (const t of latin) out.push(t)
  // CJK 2-char bigrams.
  const cjkRuns = content.match(/[一-鿿぀-ゟ゠-ヿ가-힯]+/g) ?? []
  for (const run of cjkRuns) {
    if (run.length === 1) out.push(run)
    else for (let i = 0; i < run.length - 1; i++) out.push(run.slice(i, i + 2))
  }
  return out
}

// ── Promotion decision ─────────────────────────────────────────────────

export interface PromotionInput {
  candidates: MemoryCandidate[]
  outcome: TurnOutcome
  userMessage: string
  /**
   * Optional — a candidate whose claimedSource === 'user_stated' but
   * whose sourceQuote fails verification is demoted here.
   */
  revision: RevisionBinding
  /**
   * v0.5.3 Hotfix §2: tool-call registry used to validate
   * tool_observed evidence refs. The MemoryModule.onComplete
   * path collects ToolResults from the run-scoped context; this
   * map (toolCallId → resultQuote) lets decidePromotion drop
   * tool_observed candidates whose toolCallId is unknown or
   * whose resultQuote isn't in the actual result.
   *
   * When absent, tool_observed with tool_result refs are
   * accepted at the structural level (no further validation);
   * this keeps the pure function usable in unit tests.
   */
  toolCallRegistry?: Map<string, { resultText: string; truncated: boolean; isError: boolean }>
  /**
   * v0.5.5 §3: project identity for file evidence validation.
   * File evidence paths are resolved against
   * `projectIdentity.canonicalRoot` and must not escape it.
   * Optional — without it, file evidence refs are rejected
   * outright (no escape validation possible).
   */
  projectIdentity?: { canonicalRoot: string }
  /**
   * v0.5.5 §3: evidence store lookup for verification refs.
   * Keys are evidenceId. Only entries with status='passed' AND
   * createdAt in the current run window are accepted.
   */
  evidenceStore?: { get(id: string): { status: string; createdAt: number } | undefined }
}

export interface PromotionDecision {
  /** Candidates that will be promoted to kind semantic/procedural with verified=true. */
  successPromotions: Array<{ candidate: MemoryCandidate; memoryInput: Omit<MemoryRecord, 'id' | 'createdAt'> }>
  /** Candidates that will be promoted to kind failure with verified=false. */
  failurePromotions: Array<{ candidate: MemoryCandidate; memoryInput: Omit<MemoryRecord, 'id' | 'createdAt'> }>
  /** Candidates dropped without writing. Each reason is recorded. */
  dropped: Array<{ candidateId: string; reason: string }>
}

/**
 * Decide which candidates to promote based on the run outcome and
 * the rules above. Pure function — does not write anywhere. The
 * caller (MemoryPromoter.apply) writes the records.
 */
/**
 * v0.5.5 §3: classify whether agent_inferred evidence is
 * "strong enough" to land as verified=true. Pure function — no
 * I/O. The actual file existence + contentHash checks happen
 * elsewhere (runContext layer) and the outcome is fed in via
 * `evidenceCheck` for callers that want pre-computed file
 * verification.
 */
export function classifyAgentInferredEvidence(
  refs: ReadonlyArray<import('./memoryCandidate.js').MemoryEvidenceRef | { kind: string }>,
  input: Pick<PromotionInput, 'toolCallRegistry' | 'projectIdentity' | 'evidenceStore'>,
  evidenceCheck?: (path: string) => { exists: boolean; hashMatches: boolean | null },
): { ok: true; strong: 'tool_result' | 'file_hash' | 'verification' } | { ok: false; reason: string } {
  const toolRefs = refs.filter((r): r is { kind: 'tool_result'; toolCallId: string; resultQuote: string } =>
    (r as { kind?: string }).kind === 'tool_result')
  const fileRefs = refs.filter((r): r is { kind: 'file'; path: string; contentHash?: string } =>
    (r as { kind?: string }).kind === 'file')
  const verifRefs = refs.filter((r): r is { kind: 'verification'; evidenceId: string } =>
    (r as { kind?: string }).kind === 'verification')

  // Tool-result refs are strong ONLY when the registry proves them.
  if (toolRefs.length > 0 && input.toolCallRegistry) {
    for (const ref of toolRefs) {
      const entry = input.toolCallRegistry.get(ref.toolCallId)
      if (entry && !entry.isError && !entry.truncated && entry.resultText.includes(ref.resultQuote)) {
        return { ok: true, strong: 'tool_result' }
      }
    }
  }

  // Verification refs are strong ONLY when the evidence store
  // confirms a passed status AND the entry is recent.
  if (verifRefs.length > 0 && input.evidenceStore) {
    for (const ref of verifRefs) {
      const e = input.evidenceStore.get(ref.evidenceId)
      if (e && e.status === 'passed') {
        return { ok: true, strong: 'verification' }
      }
    }
  }

  // File refs are strong ONLY when contentHash is provided AND
  // (a) the optional evidenceCheck proves the file exists + hash
  // matches, OR (b) no evidenceCheck is supplied (best-effort
  // hash record — the Run layer verifies if available).
  for (const ref of fileRefs) {
    if (ref.contentHash) {
      if (!evidenceCheck) return { ok: true, strong: 'file_hash' }
      const check = evidenceCheck(ref.path)
      if (check.exists && check.hashMatches === true) {
        return { ok: true, strong: 'file_hash' }
      }
    }
  }
  // Weak file refs paired with one strong ref → strong
  if (fileRefs.length > 0 && (toolRefs.length > 0 || verifRefs.length > 0)) {
    return { ok: true, strong: 'verification' }
  }
  return { ok: false, reason: 'agent_inferred has no strong evidence (file refs require contentHash + verified hash; tool_result refs require registry match; verification refs require passed status)' }
}

export function decidePromotion(input: PromotionInput): PromotionDecision {
  const successPromotions: PromotionDecision['successPromotions'] = []
  const failurePromotions: PromotionDecision['failurePromotions'] = []
  const dropped: PromotionDecision['dropped'] = []

  const outcome = input.outcome
  const status: CompletionStatus = outcome.completion.status
  const verification = outcome.verification
  const unresolvedCount = outcome.completion.requiredNextActions.length

  // Promotion gates (v0.5.3 Final — task 2):
  //   - status === 'completed'
  //   - verification.executed
  //   - verification.passed
  //   - verification.failed empty
  //   - no unresolved next-actions
  const isFullSuccess =
    status === 'completed' &&
    verification.executed &&
    verification.passed &&
    verification.failed.length === 0 &&
    unresolvedCount === 0

  for (const c of input.candidates) {
    // v0.5.3 Hotfix §2 — Claim-Level Evidence.
    //
    // user_stated: drop unconditionally on verification failure.
    //   No demote, no silent launder. (P0 fix from previous round.)
    // tool_observed: verify via evidenceRefs (tool_result toolCallId
    //   belongs to the run + resultQuote exists in real result +
    //   no truncation).
    // agent_inferred without evidence: NEVER verified=true. Either
    //   dropped, or saved as kind='reflection', verified=false.
    let effectiveSource: ClaimedMemorySource = c.claimedSource

    if (c.claimedSource === 'user_stated') {
      const verdict = verifySourceQuote({
        sourceQuote: c.sourceQuote,
        userMessage: input.userMessage,
        content: c.content,
      })
      if (verdict.result === 'drop') {
        // v0.5.3 Hotfix §2: user_stated failures ALWAYS drop. No
        // demote-to-agent_inferred on success runs. The candidate
        // contributes nothing to memory.
        dropped.push({ candidateId: c.id, reason: verdict.reason })
        continue
      }
      if (verdict.result === 'demote-agent_inferred') {
        // Kept as a deprecated back-compat branch. New behaviour
        // treats demote the same as drop.
        dropped.push({ candidateId: c.id, reason: verdict.reason })
        continue
      }
      // 'verified' → keep user_stated.
    } else if (c.claimedSource === 'tool_observed') {
      // v0.5.3 Hotfix §2: tool_observed requires a tool_result
      // evidence ref AND that ref must verify against a real
      // ToolResult in this run.
      const toolRefs = (c.evidenceRefs ?? []).filter((r) => r.kind === 'tool_result')
      if (toolRefs.length === 0) {
        dropped.push({
          candidateId: c.id,
          reason: 'tool_observed without tool_result evidence ref',
        })
        continue
      }
      // Promotion-time registry check: every toolCallId must be
      // present in the run's actual tool-call registry. The
      // resultQuote must appear in the recorded resultText, the
      // result must not be truncated, and must not be an error.
      if (input.toolCallRegistry) {
        const registry = input.toolCallRegistry
        let toolEvidenceOk = true
        for (const ref of toolRefs) {
          if (ref.kind !== 'tool_result') continue
          const entry = registry.get(ref.toolCallId)
          if (!entry) {
            dropped.push({
              candidateId: c.id,
              reason: `tool_observed references unknown toolCallId ${ref.toolCallId}`,
            })
            toolEvidenceOk = false
            break
          }
          if (entry.truncated) {
            dropped.push({
              candidateId: c.id,
              reason: `tool_observed toolCallId ${ref.toolCallId} result is truncated (unverifiable)`,
            })
            toolEvidenceOk = false
            break
          }
          if (entry.isError) {
            dropped.push({
              candidateId: c.id,
              reason: `tool_observed toolCallId ${ref.toolCallId} result was an error`,
            })
            toolEvidenceOk = false
            break
          }
          if (!entry.resultText.includes(ref.resultQuote)) {
            dropped.push({
              candidateId: c.id,
              reason: `tool_observed toolCallId ${ref.toolCallId} resultQuote not found in ToolResult`,
            })
            toolEvidenceOk = false
            break
          }
        }
        if (!toolEvidenceOk) continue
      }
    } else if (c.claimedSource === 'agent_inferred') {
      // v0.5.5 §3: agent_inferred evidence must satisfy strong-evidence
      // requirements to land as verified=true. Strong evidence =
      //   (tool_result OR file-with-contentHash OR verification).
      //   Bare file refs without contentHash are WEAK and must be
      //   paired with another strong ref to qualify.
      // No evidence at all → never verified=true on success runs.
      const refs = c.evidenceRefs ?? []
      const strongResult = classifyAgentInferredEvidence(refs, input)
      if (!strongResult.ok) {
        if (isFullSuccess) {
          dropped.push({
            candidateId: c.id,
            reason: strongResult.reason ?? 'agent_inferred without strong evidence',
          })
          continue
        }
        // Failure run: keep as reflection audit (verified=false).
        effectiveSource = 'agent_inferred'
      }
    }

    if (isFullSuccess) {
      const kind: MemoryKind = effectiveSource === 'agent_inferred' ? 'semantic' : 'semantic'
      const memoryInput: Omit<MemoryRecord, 'id' | 'createdAt'> = {
        kind,
        content: c.content.slice(0, 500),
        repo: input.revision.repo,
        branch: input.revision.branch,
        // v0.5.3 Hotfix §3: baseCommit is the canonical internal
        // field. `commit` is read-only compat alias; new writes
        // MUST NOT use it.
        baseCommit: input.revision.baseCommit,
        dirty: input.revision.dirty,
        diffHash: input.revision.diffHash,
        workspaceHash: input.revision.workspaceHash,
        sourceRunId: c.runId,
        origin: effectiveSource === 'user_stated' ? 'user_prompt' : `memory_promotion:${c.runId}`,
        confidence: c.confidence,
        verified: true,
        tags: [
          ...c.tags,
          'promoted',
          `run:${c.runId}`,
          `source:${effectiveSource}`,
        ],
        expiresAt: undefined,
      }
      successPromotions.push({ candidate: c, memoryInput })
    } else {
      // Failure / partial / blocked / cancelled / exhausted:
      // any non-completed outcome routes the candidate to the
      // failure branch — verified=false, kind='failure'. These
      // entries never enter the success-memory read pool.
      const memoryInput: Omit<MemoryRecord, 'id' | 'createdAt'> = {
        kind: 'failure',
        content: c.content.slice(0, 500),
        repo: input.revision.repo,
        branch: input.revision.branch,
        baseCommit: input.revision.baseCommit,
        dirty: input.revision.dirty,
        diffHash: input.revision.diffHash,
        workspaceHash: input.revision.workspaceHash,
        sourceRunId: c.runId,
        origin: `memory_promotion:${c.runId}:failure:${status}`,
        confidence: c.confidence,
        verified: false,
        tags: [
          ...c.tags,
          'promoted-failure',
          `run:${c.runId}`,
          `outcome:${status}`,
        ],
        expiresAt: undefined,
      }
      failurePromotions.push({ candidate: c, memoryInput })
    }
  }

  return { successPromotions, failurePromotions, dropped }
}

// ── Helpers ─────────────────────────────────────────────────────────────

export function makeCandidateId(): string {
  return `mc_${randomUUID()}`
}

/**
 * Stable, deterministic hash for non-Git workspaces. SHA-256 of
 * `cwd + ":" + epoch_second_bucket`. We bucket by minute to keep the
 * hash stable across a single session; if the user actually moves
 * the workspace, the bucket changes too.
 */
export function workspaceHash(cwd: string): string {
  const minuteBucket = Math.floor(Date.now() / 60_000)
  return createHash('sha256').update(`${cwd}:${minuteBucket}`).digest('hex')
}

/**
 * AnthropicAdapter — R8: now uses @anthropic-ai/sdk directly.
 *
 * We translate Anthropic SDK's `MessageStreamEvent`s into OpenAI's
 * `ChatCompletionChunk` shape so the existing StreamConsumer doesn't
 * change. Beta headers (prompt caching, extended thinking) are
 * forwarded via providerOptions.
 */

import type OpenAI from 'openai'
import Anthropic from '@anthropic-ai/sdk'
import type { ProviderAdapter, ProviderStreamRequest } from './providerAdapter.js'
import {
  AnthropicChunkTranslator,
  buildAnthropicRequest,
  extractAnthropicBetaHeaders,
  type AnthropicProviderOptions,
} from './anthropicSse.js'

export interface AnthropicAdapterConfig {
  apiKey: string
  baseURL?: string
  defaultMaxTokens?: number
  apiVersion?: string
}

const ANTHROPIC_DEFAULT_BASE_URL = 'https://api.anthropic.com'
const ANTHROPIC_DEFAULT_MAX_TOKENS = 8192

export class AnthropicAdapter implements ProviderAdapter {
  readonly providerId = 'anthropic'
  private readonly client: Anthropic
  private readonly defaultMaxTokens: number
  private _streamUsageSupported = true

  constructor(config: AnthropicAdapterConfig) {
    const clientConfig: { apiKey: string; baseURL?: string } = { apiKey: config.apiKey }
    if (config.baseURL) clientConfig.baseURL = config.baseURL
    this.client = new Anthropic(clientConfig)
    this.defaultMaxTokens = config.defaultMaxTokens ?? ANTHROPIC_DEFAULT_MAX_TOKENS
  }

  get streamUsageSupported(): boolean {
    return this._streamUsageSupported
  }

  resetStreamUsageLatch(): void {
    this._streamUsageSupported = true
  }

  markStreamUsageUnsupported(): void {
    this._streamUsageSupported = false
  }

  async stream(req: ProviderStreamRequest): Promise<AsyncIterable<OpenAI.Chat.ChatCompletionChunk>> {
    const providerOptions = (req as ProviderStreamRequest & { providerOptions?: AnthropicProviderOptions }).providerOptions
    const maxTokens = req.maxOutputTokens ?? this.defaultMaxTokens

    const { system, messages } = convertOpenAIMessages(req.messages, req.systemPrompt)
    const params = buildAnthropicRequest({
      model: req.model,
      systemPrompt: system,
      messages: messages,
      tools: req.tools,
      maxTokens,
      temperature: req.temperature,
      providerOptions,
    })

    const betaHeaders = extractAnthropicBetaHeaders(providerOptions)
    const betaHeader = betaHeaders.length > 0 ? betaHeaders.join(',') : undefined

    return this.iterate(params, req.model, req.signal, betaHeader)
  }

  private async *iterate(
    params: ReturnType<typeof buildAnthropicRequest>,
    modelId: string,
    signal: AbortSignal | undefined,
    betaHeader: string | undefined,
  ): AsyncGenerator<OpenAI.Chat.ChatCompletionChunk> {
    const translator = new AnthropicChunkTranslator(modelId)
    try {
      // R8: pass beta header via SDK options defaultHeaders (SDK supports it)
      // We use the `anthropic-beta` header through the `extraHeaders` proxy
      // (older SDKs) or via the explicit `anthropicBeta` field on params.
      if (betaHeader) {
        ;(params as unknown as { anthropic_beta?: string }).anthropic_beta = betaHeader
      }
      const options: { signal?: AbortSignal } = {}
      if (signal) options.signal = signal
      const sdkStream = this.client.messages.stream(params, options)
      for await (const event of sdkStream) {
        if (signal?.aborted) {
          sdkStream.controller.abort()
          throw new Error('aborted')
        }
        const translated = translateEvent(event, translator)
        for (const chunk of translated) {
          yield chunk
        }
      }
      const final = translator.finalizeWithUsage(undefined)
      yield final
    } catch (err: unknown) {
      if (signal?.aborted) throw new Error('aborted')
      throw err instanceof Error ? err : new Error(String(err))
    }
  }
}

interface OpenAIContentPart {
  type: 'text' | 'image_url'
  text?: string
  image_url?: { url: string }
}

interface OpenAIToolCall {
  id: string
  type: 'function'
  function: { name: string; arguments: string }
}

 
function isOpenAIToolCall(value: unknown): value is OpenAIToolCall {
  if (!value || typeof value !== 'object') return false
  const obj = value as Record<string, unknown>
  if (obj.type !== 'function') return false
   
  const fn = obj.function
  if (!fn || typeof fn !== 'object') return false
  const fnObj = fn as Record<string, unknown>
  return typeof fnObj.name === 'string' && typeof fnObj.arguments === 'string'
}

function isOpenAITextPart(value: unknown): value is { type: 'text'; text: string } {
  if (!value || typeof value !== 'object') return false
  const obj = value as Record<string, unknown>
  return obj.type === 'text' && typeof obj.text === 'string'
}

function isOpenAIImagePart(value: unknown): value is { type: 'image_url'; image_url: { url: string } } {
  if (!value || typeof value !== 'object') return false
  const obj = value as Record<string, unknown>
  if (obj.type !== 'image_url') return false
  const img = obj.image_url
  if (!img || typeof img !== 'object') return false
  return typeof (img as Record<string, unknown>).url === 'string'
}

function convertOpenAIMessages(
  messages: OpenAI.Chat.ChatCompletionMessageParam[],
  systemPrompt: string,
): { system: string; messages: Array<{ role: 'user' | 'assistant'; content: string | Array<Record<string, unknown>> }> } {
  const converted: Array<{ role: 'user' | 'assistant'; content: string | Array<Record<string, unknown>> }> = []
  for (const msg of messages) {
    const role = (msg as { role: string }).role
    if (role === 'system') continue
    if (role === 'tool') {
      const toolCallId = (msg as { tool_call_id?: string }).tool_call_id
      const content = (msg as { content?: unknown }).content
      const text = typeof content === 'string' ? content : Array.isArray(content)
        ? content.map((p) => isOpenAITextPart(p) ? p.text : '').join('\n')
        : ''
      const isError = (msg as { is_error?: boolean }).is_error === true
      converted.push({
        role: 'user',
        content: [{
          type: 'tool_result',
          tool_use_id: toolCallId ?? '',
          content: text,
          is_error: isError,
        }],
      })
      continue
    }
    if (role === 'user') {
      const content = (msg as { content?: unknown }).content
      if (typeof content === 'string') {
        converted.push({ role: 'user', content })
      } else if (Array.isArray(content)) {
        const blocks: Array<Record<string, unknown>> = []
        for (const part of content) {
          if (isOpenAITextPart(part)) {
            blocks.push({ type: 'text', text: part.text })
          } else if (isOpenAIImagePart(part)) {
            const url = part.image_url.url
            if (url.startsWith('data:')) {
              const match = url.match(/^data:([^;]+);base64,(.+)$/)
              if (match) {
                blocks.push({
                  type: 'image',
                  source: { type: 'base64', media_type: match[1], data: match[2] },
                })
              }
            }
          }
        }
        converted.push({ role: 'user', content: blocks.length > 0 ? blocks : (Array.isArray(content) ? content : []) })
      } else {
        converted.push({ role: 'user', content: '' })
      }
      continue
    }
    if (role === 'assistant') {
      const toolCallsRaw = (msg as { tool_calls?: unknown }).tool_calls
      const toolCalls = Array.isArray(toolCallsRaw) ? toolCallsRaw.filter(isOpenAIToolCall) : []
      const text = (msg as { content?: unknown }).content
      const blocks: Array<Record<string, unknown>> = []
      if (typeof text === 'string' && text) {
        blocks.push({ type: 'text', text })
      }
      for (const tc of toolCalls) {
        let input: unknown = {}
        try { input = JSON.parse(tc.function.arguments || '{}') } catch { input = {} }
        blocks.push({
          type: 'tool_use',
          id: tc.id,
          name: tc.function.name,
          input,
        })
      }
      if (blocks.length === 0) {
        converted.push({ role: 'assistant', content: '' })
      } else {
        converted.push({ role: 'assistant', content: blocks })
      }
    }
  }
  return { system: systemPrompt, messages: converted }
}

type AdaptedEvent = Parameters<AnthropicChunkTranslator['push']>[0]

function translateEvent(
  event: Anthropic.MessageStreamEvent,
  translator: AnthropicChunkTranslator,
): OpenAI.Chat.ChatCompletionChunk[] {
  const adapted = adaptEvent(event)
  if (adapted) return translator.push(adapted as unknown as AdaptedEvent)
  return []
}

function adaptEvent(event: Anthropic.MessageStreamEvent): Record<string, unknown> | null {
  const e = event as unknown as Record<string, unknown> & { type: string }
  switch (e.type) {
    case 'message_start': {
      const m = (e.message ?? {}) as Record<string, unknown>
      const usage = m.usage as { input_tokens?: number; output_tokens?: number } | undefined
      return {
        type: 'message_start',
        message: {
          id: m.id,
          type: 'message',
          role: m.role,
          content: m.content,
          model: m.model,
          stop_reason: m.stop_reason,
          usage: usage ? { input_tokens: usage.input_tokens ?? 0, output_tokens: usage.output_tokens ?? 0 } : undefined,
        },
      }
    }
    case 'content_block_start': {
      const cb = (e.content_block ?? {}) as { type: string; id?: string; name?: string; input?: unknown; text?: string }
      const content_block = cb.type === 'tool_use'
        ? { type: 'tool_use', id: cb.id, name: cb.name, input: cb.input }
        : { type: 'text', text: cb.type === 'text' ? (cb.text ?? '') : '' }
      return { type: 'content_block_start', index: e.index, content_block }
    }
    case 'content_block_delta': {
      const delta = (e.delta ?? {}) as { type?: string; text?: string; partial_json?: string; thinking?: string; signature?: string }
      if (delta.type === 'text_delta') {
        return { type: 'content_block_delta', index: e.index, delta: { type: 'text_delta', text: delta.text ?? '' } }
      }
      if (delta.type === 'input_json_delta') {
        return { type: 'content_block_delta', index: e.index, delta: { type: 'input_json_delta', partial_json: delta.partial_json ?? '' } }
      }
      if (delta.type === 'thinking_delta') {
        return { type: 'content_block_delta', index: e.index, delta: { type: 'thinking_delta', thinking: delta.thinking ?? '' } }
      }
      if (delta.type === 'signature_delta') {
        return { type: 'content_block_delta', index: e.index, delta: { type: 'signature_delta', signature: delta.signature ?? '' } }
      }
      return null
    }
    case 'content_block_stop':
      return { type: 'content_block_stop', index: e.index }
    case 'message_delta': {
      const d = (e.delta ?? {}) as { stop_reason?: string | null; stop_sequence?: string | null }
      const usage = e.usage as { output_tokens?: number } | undefined
      return {
        type: 'message_delta',
        delta: {
          stop_reason: d.stop_reason ?? null,
          stop_sequence: d.stop_sequence ?? null,
        },
        usage: usage ? { output_tokens: usage.output_tokens ?? 0 } : undefined,
      }
    }
    case 'message_stop':
      return { type: 'message_stop' }
    case 'ping':
      return { type: 'ping' }
    case 'error': {
      const err = (e.error ?? {}) as { type: string; message: string }
      return { type: 'error', error: { type: err.type, message: err.message } }
    }
    default:
      return null
  }
}

/**
 * Anthropic request body builder + OpenAI ChatCompletionChunk translator.
 *
 * R8: the SSE parser itself was replaced with `@anthropic-ai/sdk`'s
 * built-in event stream (`client.messages.stream()`). We keep only the
 * two pieces that don't ship in any SDK:
 *
 *   1. `buildAnthropicRequest()` — translates OpenAI ChatCompletionRequest
 *      fields (systemPrompt, tools, maxTokens, temperature) into the
 *      Anthropic Messages API shape, with optional providerOptions for
 *      prompt caching + extended thinking.
 *   2. `AnthropicChunkTranslator` — translates SDK `MessageStreamEvent`s
 *      into OpenAI `ChatCompletionChunk` so the existing StreamConsumer
 *      doesn't change.
 *
 * Note: `extractAnthropicBetaHeaders()` is also kept here because it
 * decides which `anthropic-beta:` header to add to the request (the
 * SDK doesn't expose a clean way to override this from outside).
 */

import Anthropic from '@anthropic-ai/sdk'
import type OpenAI from 'openai'

export type AnthropicEvent =
  | { type: 'message_start'; message: { id: string; type: string; role: string; content: unknown[]; model: string; stop_reason: string | null; usage?: { input_tokens: number; output_tokens: number } } }
  | { type: 'content_block_start'; index: number; content_block: { type: string; id?: string; name?: string; input?: unknown; text?: string } }
  | { type: 'content_block_delta'; index: number; delta: { type: 'text_delta'; text: string } | { type: 'input_json_delta'; partial_json: string } | { type: 'thinking_delta'; thinking: string } | { type: 'signature_delta'; signature: string } }
  | { type: 'content_block_stop'; index: number }
  | { type: 'message_delta'; delta: { stop_reason: string | null; stop_sequence: string | null }; usage?: { output_tokens: number } }
  | { type: 'message_stop' }
  | { type: 'ping' }
  | { type: 'error'; error: { type: string; message: string } }

export interface AnthropicProviderOptions {
  anthropicBeta?: string[]
  cacheSystem?: boolean
  cacheTools?: boolean
  thinkingBudget?: number
}

interface ToolAccumulator {
  id: string
  name: string
  args: string
  sentInitialChunk: boolean
}

export function buildAnthropicRequest(input: {
  model: string
  systemPrompt: string
  messages: Array<{ role: 'user' | 'assistant'; content: string | Array<Record<string, unknown>> }>
  tools: Array<{ type: 'function'; function: { name: string; description?: string; parameters?: Record<string, unknown> } }>
  maxTokens: number
  temperature?: number
  providerOptions?: AnthropicProviderOptions
}): Anthropic.MessageCreateParamsNonStreaming {
  const anthropicTools: Anthropic.Tool[] = (input.tools ?? []).map((tool, idx, all) => {
    const isLast = idx === all.length - 1
    const t: Anthropic.Tool = {
      name: tool.function.name,
      description: tool.function.description ?? '',
      input_schema: (tool.function.parameters ?? { type: 'object', properties: {} }) as Anthropic.Tool.InputSchema,
    }
    if (isLast && input.providerOptions?.cacheTools) {
      return { ...t, cache_control: { type: 'ephemeral' } } as Anthropic.Tool
    }
    return t
  })

  const systemBlocks: Anthropic.MessageCreateParamsNonStreaming['system'] = input.providerOptions?.cacheSystem
    ? [{ type: 'text', text: input.systemPrompt, cache_control: { type: 'ephemeral' } } as Anthropic.TextBlockParam]
    : input.systemPrompt

  const params: Anthropic.MessageCreateParamsNonStreaming = {
    model: input.model,
    system: systemBlocks,
    messages: input.messages.map((m) => ({
      role: m.role,
      content: m.content as Anthropic.MessageParam['content'],
    })),
    tools: anthropicTools,
    max_tokens: input.maxTokens,
    temperature: input.temperature,
  }

  if (input.providerOptions?.thinkingBudget && input.providerOptions.thinkingBudget > 0) {
    (params as { thinking?: unknown }).thinking = {
      type: 'enabled',
      budget_tokens: input.providerOptions.thinkingBudget,
    }
  }

  return params
}

export function extractAnthropicBetaHeaders(providerOptions?: AnthropicProviderOptions): string[] {
  if (!providerOptions?.anthropicBeta || providerOptions.anthropicBeta.length === 0) return []
  if (providerOptions.thinkingBudget && providerOptions.thinkingBudget > 0
    && !providerOptions.anthropicBeta.some((b) => b.includes('thinking'))) {
    return [...providerOptions.anthropicBeta, 'extended-thinking-2025-01-01']
  }
  return providerOptions.anthropicBeta
}

/**
 * Translate Anthropic SDK `MessageStreamEvent`s into OpenAI
 * `ChatCompletionChunk`s. Maintains tool-call accumulator state per
 * stream index and emits synthetic OpenAI delta chunks.
 *
 * Kept for backward compatibility — the AnthropicAdapter still feeds
 * events through this translator so StreamConsumer doesn't change.
 */
export class AnthropicChunkTranslator {
  private readonly chunks: OpenAI.Chat.ChatCompletionChunk[] = []
  private readonly toolAccumulators = new Map<number, ToolAccumulator>()
  private readonly modelId: string
  private inputTokens = 0
  private outputTokens = 0
  private finishReason: string | null = null
  private readonly created: number

  constructor(modelId: string) {
    this.modelId = modelId
    this.created = Math.floor(Date.now() / 1000)
  }

  push(event: AnthropicEvent): OpenAI.Chat.ChatCompletionChunk[] {
    const out: OpenAI.Chat.ChatCompletionChunk[] = []
    switch (event.type) {
      case 'message_start': {
        this.inputTokens = event.message.usage?.input_tokens ?? 0
        if (event.message.usage?.output_tokens) {
          this.outputTokens = event.message.usage.output_tokens
        }
        break
      }
      case 'content_block_start': {
        if (event.content_block.type === 'tool_use') {
          const acc: ToolAccumulator = {
            id: event.content_block.id ?? `toolu_${event.index}`,
            name: event.content_block.name ?? '',
            args: '',
            sentInitialChunk: false,
          }
          this.toolAccumulators.set(event.index, acc)
          out.push(this.makeChunk({
            choices: [{
              index: 0,
              delta: {
                tool_calls: [{
                  index: event.index,
                  id: acc.id,
                  type: 'function',
                  function: { name: acc.name, arguments: '' },
                }],
              },
            }],
          }))
          acc.sentInitialChunk = true
        }
        break
      }
      case 'content_block_delta': {
        const delta = event.delta
        if (delta.type === 'text_delta') {
          out.push(this.makeChunk({
            choices: [{
              index: 0,
              delta: { content: delta.text },
            }],
          }))
        } else if (delta.type === 'input_json_delta') {
          const acc = this.toolAccumulators.get(event.index)
          if (acc) {
            acc.args += delta.partial_json
            out.push(this.makeChunk({
              choices: [{
                index: 0,
                delta: {
                  tool_calls: [{
                    index: event.index,
                    function: { arguments: delta.partial_json },
                  }],
                },
              }],
            }))
          }
        }
        break
      }
      case 'message_delta': {
        if (event.delta.stop_reason) this.finishReason = event.delta.stop_reason
        if (event.usage?.output_tokens) this.outputTokens += event.usage.output_tokens
        break
      }
      case 'message_stop': {
        out.push(this.makeChunk({
          choices: [{
            index: 0,
            delta: {},
            finish_reason: this.mapFinishReason(this.finishReason),
          }],
          usage: this.outputTokens > 0
            ? {
                prompt_tokens: this.inputTokens,
                completion_tokens: this.outputTokens,
                total_tokens: this.inputTokens + this.outputTokens,
              }
            : undefined,
        }))
        break
      }
      default:
        break
    }
    this.chunks.push(...out)
    return out
  }

  private makeChunk(payload: {
    choices: Array<{ index: number; delta: Record<string, unknown>; finish_reason?: string }>
    usage?: { prompt_tokens: number; completion_tokens: number; total_tokens: number }
  }): OpenAI.Chat.ChatCompletionChunk {
    const chunk: OpenAI.Chat.ChatCompletionChunk = {
      id: `chatcmpl-${Date.now().toString(36)}`,
      object: 'chat.completion.chunk',
      created: this.created,
      model: this.modelId,
      choices: payload.choices.map((c) => ({
        index: c.index,
        delta: c.delta,
        finish_reason: c.finish_reason as OpenAI.Chat.ChatCompletionChunk.Choice['finish_reason'],
        logprobs: null,
      })),
    }
    if (payload.usage) {
      chunk.usage = {
        prompt_tokens: payload.usage.prompt_tokens,
        completion_tokens: payload.usage.completion_tokens,
        total_tokens: payload.usage.total_tokens,
      }
    }
    return chunk
  }

  private mapFinishReason(reason: string | null): string {
    switch (reason) {
      case 'end_turn':
      case 'stop_sequence':
        return 'stop'
      case 'max_tokens':
        return 'length'
      case 'tool_use':
        return 'tool_calls'
      case null:
      case undefined:
        return 'stop'
      default:
        return 'stop'
    }
  }

  finalizeWithUsage(usage: { inputTokens?: number; outputTokens?: number } | undefined): OpenAI.Chat.ChatCompletionChunk {
    const inputTokens = usage?.inputTokens ?? this.inputTokens
    const outputTokens = usage?.outputTokens ?? this.outputTokens
    const chunk = this.makeChunk({
      choices: [{
        index: 0,
        delta: {},
        finish_reason: this.mapFinishReason(this.finishReason ?? 'end_turn'),
      }],
      usage: {
        prompt_tokens: inputTokens,
        completion_tokens: outputTokens,
        total_tokens: inputTokens + outputTokens,
      },
    })
    this.chunks.push(chunk)
    return chunk
  }
}

export { Anthropic }

export function buildAssistantMessageToAnthropicContent(
  text: string | null,
  toolCalls: Array<{ id: string; name: string; arguments: string }>,
): Array<Record<string, unknown>> {
  const blocks: Array<Record<string, unknown>> = []
  if (text) blocks.push({ type: 'text', text })
  for (const tc of toolCalls) {
    let input: unknown = {}
    try { input = JSON.parse(tc.arguments || '{}') } catch { input = {} }
    blocks.push({ type: 'tool_use', id: tc.id, name: tc.name, input })
  }
  return blocks
}

export function toolResultToAnthropicUserBlock(toolCallId: string, content: string, isError: boolean): Record<string, unknown> {
  return {
    type: 'tool_result',
    tool_use_id: toolCallId,
    content,
    is_error: isError,
  }
}

/**
 * ProviderAdapter (provider-runtime contract Phase 1) — the single abstraction that owns
 * provider-specific request shape and streaming establishment.
 *
 * ModelGateway delegates ALL model I/O to a ProviderAdapter. The
 * coordinator never branches on provider; the adapter hides:
 *   - request body shape (system-as-message vs top-level, tool schema)
 *   - streaming transport (OpenAI chunk array vs Anthropic SSE events)
 *   - provider quirks (stream_options.include_usage probing, etc.)
 *
 * Contract: every adapter normalises its provider's native stream into
 * OpenAI ChatCompletionChunk shape. This keeps StreamConsumer (and the
 * whole tool_call accumulation pipeline) provider-agnostic WITHOUT a
 * risky full re-typing of the stream — OpenAICompatibleAdapter is the
 * identity transform; a future AnthropicAdapter translates
 * message_start/content_block_delta SSE into the same chunk shape.
 *
 * Selection: `createProviderAdapter(config)` picks the adapter from
 * `config.provider` / baseURL. Today both 'openai' and 'minimax' route
 * through OpenAICompatibleAdapter (MiniMax M3 is served OpenAI-
 * compatible at /v1; the bin rewrites /anthropic -> /v1). Adding a new
 * provider = implement ProviderAdapter + register it in the factory.
 */

import type OpenAI from 'openai'
import type { ToolDefinition } from '../types.js'
import { AnthropicAdapter } from './anthropicAdapter.js'

export { AnthropicAdapter } from './anthropicAdapter.js'

export type ProviderId = string

/**
 * Provider-agnostic description of one model stream request. The adapter
 * combines `systemPrompt` + `messages` per its provider's convention.
 */
export interface ProviderStreamRequest {
  model: string
  systemPrompt: string
  messages: OpenAI.Chat.ChatCompletionMessageParam[]
  tools: ToolDefinition[]
  temperature?: number
  maxOutputTokens: number
  signal: AbortSignal
}

export interface ProviderAdapter {
  /** Stable id for logging/registry (e.g. 'openai-compatible', 'anthropic'). */
  readonly providerId: ProviderId
  /**
   * Whether the provider's stream currently includes usage tokens.
   * Probed at runtime (some OpenAI-compatible backends reject
   * stream_options). ModelGateway reads this to decide whether to
   * synthesise missing usage.
   */
  readonly streamUsageSupported: boolean
  /**
   * Clear the usage-streaming probe latch. Called on model switch so a
   * move from a provider that rejects stream_options to one that
   * supports it re-probes instead of staying permanently disabled.
   */
  resetStreamUsageLatch(): void
  /**
   * Force-disable usage streaming (e.g. an out-of-band signal that the
   * backend can't supply usage). The streaming path then skips the
   * stream_options probe.
   */
  markStreamUsageUnsupported(): void
  /**
   * Establish the streaming response. Resolves to an async iterable of
   * OpenAI-shaped chunks. Throws provider errors (caller — ModelGateway
   * — handles context-overflow + retry; re-aborts propagate the signal).
   */
  stream(req: ProviderStreamRequest): Promise<AsyncIterable<OpenAI.Chat.ChatCompletionChunk>>
}

/**
 * OpenAI-compatible adapter. Wraps the OpenAI SDK client and owns the
 * request shape + the stream_options.include_usage probe/fallback that
 * previously lived inside ModelGateway. Byte-equivalent to the legacy
 * direct-SDK path so existing OpenAI / MiniMax (/v1) / OpenRouter /
 * Ollama / etc. configurations keep working unchanged.
 */
export class OpenAICompatibleAdapter implements ProviderAdapter {
  readonly providerId: string
  private _streamUsageSupported = true

  constructor(
    private readonly client: OpenAI,
    providerId = 'openai-compatible',
  ) {
    this.providerId = providerId
  }

  get streamUsageSupported(): boolean {
    return this._streamUsageSupported
  }

  resetStreamUsageLatch(): void {
    this._streamUsageSupported = true
  }

  markStreamUsageUnsupported(): void {
    this._streamUsageSupported = false
  }

  async stream(
    req: ProviderStreamRequest,
  ): Promise<AsyncIterable<OpenAI.Chat.ChatCompletionChunk>> {
    const { model, systemPrompt, messages, tools, temperature, maxOutputTokens, signal } = req
    const baseBody = {
      model,
      messages: [
        { role: 'system' as const, content: systemPrompt },
        ...messages,
      ],
      tools: tools.length > 0 ? tools : undefined,
      tool_choice: tools.length > 0 ? ('auto' as const) : undefined,
      temperature: temperature ?? 0,
      max_tokens: maxOutputTokens,
      stream: true as const,
    }

    // Fast path: include usage streaming if the latch is on.
    if (this._streamUsageSupported) {
      try {
        return await this.client.chat.completions.create(
          { ...baseBody, stream_options: { include_usage: true } },
          { signal },
        )
      } catch (err: unknown) {
        const msg = (err as Error).message || ''
        // Provider rejects stream_options — disable the latch and retry
        // once without it. Subsequent calls skip the probe.
        if (msg.includes('stream_options') || msg.includes('stream_options is not supported')) {
          this._streamUsageSupported = false
        } else {
          throw err
        }
      }
    }

    return this.client.chat.completions.create(baseBody, { signal })
  }
}

/**
 * Select a ProviderAdapter for the given config. Today everything is
 * OpenAI-compatible (OpenAI, MiniMax via /v1, OpenRouter, Ollama, …);
 * the factory is the extension point for native Anthropic / Gemini
 * adapters. `providerId` is surfaced for logging/diagnostics.
 *
 * Phase 3: native Anthropic adapter. The factory inspects `provider`:
 *   - "anthropic" → AnthropicAdapter (uses cfg.client.apiKey as x-api-key)
 *   - everything else → OpenAICompatibleAdapter
 *
 * The Anthropic branch still accepts an OpenAI client for the apiKey
 * fallback path; new code can call `createProviderAdapter` with just
 * `{ provider: 'anthropic', client }`.
 */
export interface ProviderAdapterConfig {
  provider?: string
  client: OpenAI
}

export function createProviderAdapter(cfg: ProviderAdapterConfig): ProviderAdapter {
  const pid = (cfg.provider ?? 'openai-compatible').toLowerCase()
  if (pid === 'anthropic') {
    return new AnthropicAdapter({
      apiKey: cfg.client.apiKey ?? '',
      baseURL: (cfg.client.baseURL ?? 'https://api.anthropic.com').replace(/\/v1\/?$/, ''),
    })
  }
  if (pid === 'bedrock' || pid === 'vertex' || pid === 'foundry') {
    return new StubProviderAdapter(pid)
  }
  return new OpenAICompatibleAdapter(cfg.client, pid)
}

/**
 * Placeholder adapter for providers whose native support isn't wired yet.
 * Reports the gap honestly instead of silently falling back to OpenAI compat.
 * Listed explicitly so users can see which providers are roadmap items.
 */
export class StubProviderAdapter implements ProviderAdapter {
  readonly providerId: string
  private _streamUsageSupported = false

  constructor(providerId: string) {
    this.providerId = providerId
  }

  get streamUsageSupported(): boolean {
    return this._streamUsageSupported
  }

  resetStreamUsageLatch(): void {
    this._streamUsageSupported = false
  }

  markStreamUsageUnsupported(): void {
    this._streamUsageSupported = false
  }

  async stream(): Promise<AsyncIterable<never>> {
    throw new Error(
      `Provider "${this.providerId}" is not wired in this build of ovolv999. ` +
      'OpenAI-compatible providers and Anthropic are supported today; ' +
      'Bedrock / Vertex / Foundry are tracked in docs/roadmap.md (planned 0.6.0).',
    )
  }
}

/**
 * Module System — composable capability extensions for the unified Harness.
 *
 * Core principle (from AgentOS): all agents share one runtime (Harness).
 * Differentiated capabilities come from enabling/disabling modules, NOT from
 * hardcoded agent_type enums.
 *
 * Lifecycle hooks:
 *   boot()        — called once before the engine loop starts
 *   onIteration() — called at the top of each loop iteration
 *   onToolCall()  — called after each tool execution
 *   onComplete()  — called after the engine loop finishes
 */

import type OpenAI from 'openai'
import type { Tool, ToolContext, ToolResult, OpenAIMessage, TurnResult, EngineConfig } from './types.js'
import type { TurnOutcome } from './runtime/turnOutcome.js'
import type { EventLog } from './eventLog.js'
import type { RepoStatsService } from './repoStats.js'

/** Context passed to module factories — provides shared dependencies */
export interface ModuleContext {
  client: OpenAI
  model: string
  config: EngineConfig
}

/** Factory that creates a module instance from shared context */
export type ModuleFactory = (ctx: ModuleContext) => AgentModule

/** Context passed to module.boot() */
export interface ModuleBootContext {
  cwd: string
  sessionDir?: string
  config: EngineConfig
  /** The user's message for this run — used for relevance-based memory retrieval */
  userMessage?: string
  /**
   * v0.5.3 Hotfix §4: resolved ProjectIdentity. Modules MUST read
   * `projectIdentity.canonicalRoot` for any per-project file
   * storage or repo-filtered read. The legacy `cwd` field remains
   * populated for backwards compatibility but is the user's
   * launch directory, NOT necessarily the canonical project root.
   */
  projectIdentity?: import('./projectIdentity.js').ProjectIdentity
  /**
   * v0.5.3 (P0.2): shared services supplied by the Engine. Modules
   * MUST read these from the boot context, NOT construct their
   * own. The Engine owns one instance per service and the WorkspaceWatcher
   * uses it to invalidate the cache that the Router reads from.
   */
  sharedServices?: {
    repoStats?: RepoStatsService
  }
  /**
   * v0.5.3 (P0-1): per-turn memory provenance. The Engine stamps
   * this with the JUST-MINTED runId, the working state's
   * verification verdict, and the project cwd before invoking
   * module.boot(). Module memory_write hooks read from this on
   * every invocation; if absent (legacy test paths), the gate
   * receives `unknown` and rejects code-bound entries with a
   * clear message — that is the correct behaviour for a write
   * without provenance.
   */
  memoryToolContext?: {
    repo?: string
    branch?: string
    commit?: string
    sourceRunId?: string
    verified?: boolean
  }
}

/** Return value of module.boot() — what the module injects into the run */
export interface ModuleBootResult {
  /** Additional system prompt sections to inject */
  systemPromptSections?: string[]
  /** Additional tools this module provides */
  tools?: Tool[]
  /** Fields to merge into ToolContext */
  toolContextPatch?: Partial<ToolContext>
}

/** Context passed to module.onIteration() */
export interface ModuleIterationContext {
  iteration: number
  messages: OpenAIMessage[]
  abortSignal: AbortSignal
  /** v0.3.1: risk-gated critic signal — when true, CriticModule runs
   * immediately instead of waiting for its fixed interval. */
  criticRequested?: boolean
}

/** Return value of module.onIteration() — can inject a message into the conversation */
export interface ModuleIterationResult {
  /** If set, this message is injected as a user message before the LLM call */
  injectMessage?: string
}

/** Context passed to module.onComplete() */
export interface ModuleRunContext {
  cwd: string
  sessionDir?: string
  turnResult: TurnResult
  /** v0.3.4: the canonical TurnOutcome with completion.status */
  outcome?: TurnOutcome
  messages: OpenAIMessage[]
  eventLog?: EventLog
  /** v0.5.3 Final (task 2): the per-run RunScopedRuntimeContext, so
   *  MemoryModule.onComplete can read this run's MemoryCandidates
   *  + userMessage snapshot for promotion. */
  runContext?: import('./runtime/runScopedContext.js').RunScopedRuntimeContext
  /** v0.5.3 Final (task 2): the original user message — duplicated
   *  here for engines whose ModuleManager doesn't keep the
   *  context object alive all the way to onComplete. */
  userMessage?: string
}

/**
 * Agent Module — a composable capability extension.
 *
 * Implementations: MemoryModule, CriticModule, WorkspaceModule, ReflectionModule.
 * Custom modules can be registered via ModuleRegistry.register().
 */
export interface AgentModule {
  readonly name: string
  /** Modules that must be enabled before this one (resolved by registry) */
  readonly dependencies?: string[]
  /**
   * P0-7: criticality. `critical` (default) → boot failure aborts the
   * engine; `best_effort` → boot failure is logged and the module is
   * dropped from iteration/complete hooks. Backwards-compatible: a
   * module that omits the field is treated as `critical`.
   */
  readonly criticality?: 'critical' | 'best_effort'

  /** Boot Sequence — inject prompt sections, tools, context patches */
  boot(ctx: ModuleBootContext): ModuleBootResult | Promise<ModuleBootResult>

  /** Called at the top of each engine loop iteration (e.g. critic check) */
  onIteration?(ctx: ModuleIterationContext): void | Promise<ModuleIterationResult | void>

  /** Called after each tool execution (e.g. episodic memory write) */
  onToolCall?(
    toolName: string,
    input: Record<string, unknown>,
    result: ToolResult,
    turnNumber: number,
  ): void

  /** Called after the engine loop finishes (e.g. reflection knowledge extraction) */
  onComplete?(ctx: ModuleRunContext): void | Promise<void>

  /**
   * P0-1 (transactional model switch): called when the runtime
   * switches models mid-session. Modules that capture `model` in
   * their factory (e.g. Critic, Reflection) MUST override this so
   * subsequent LLM calls hit the new model instead of the original.
   * Optional: modules that read `model` from a live reference on
   * every call can omit it.
   */
  onModelChanged?(model: string): void
}

/**
 * ModuleManager — owns module lifecycle orchestration.
 *
 * Encapsulates the 5 module lifecycle call sites that were previously
 * scattered across engine.ts:
 *   1. Resolution (enabledModules → topological order)
 *   2. Boot (collect sections + tools + context patch)
 *   3. Iteration hooks (onIteration → inject messages)
 *   4. Tool call notification (onToolCall)
 *   5. Complete hooks (onComplete)
 *   6. Disposal (dispose?.() duck-typed on each module)
 *
 * State ownership:
 * - modules: AgentModule[] (resolved in constructor, settable for testing)
 * - bootResults: ModuleBootResult[] (per-turn, from boot)
 *
 * The engine delegates all module iteration to this manager, ensuring
 * consistent error handling:
 *   - boot: critical modules throw (abort runtime); best_effort are
 *     isolated and dropped from subsequent iteration/complete hooks.
 *   - iteration: throw (matches pre-existing contract).
 *   - complete / dispose: isolate.
 */

import type { AgentModule, ModuleBootContext, ModuleBootResult } from '../module.js'
import type { OpenAIMessage, Tool, ToolContext, ToolResult, TurnResult } from '../types.js'
import type { EventLog } from '../eventLog.js'
import type { Renderer } from '../../ui/renderer.js'
import type { TurnOutcome } from '../runtime/turnOutcome.js'

export interface ModuleManagerDeps {
  modules: AgentModule[]
  renderer: Renderer
  eventLog?: EventLog
}

export interface ModuleBootOutput {
  systemPromptSections: string[]
  tools: Tool[]
  toolContextPatch: Partial<ToolContext>
}

/**
 * P0-7: group modules into topological layers so each layer's modules
 * can boot in parallel, but layer N+1 does not start until every
 * surviving module in layer N has resolved. Modules with no
 * dependencies (or whose dependencies were filtered out) land in
 * layer 0.
 *
 * Cyclic dependencies are a hard error (runtime invariants §十二 P2-1):
 * the function THROWS, which propagates through boot() and aborts
 * engine startup. This prevents a broken module graph from booting
 * in a partially-initialised state.
 *
 * Returns an array of layers (each an AgentModule[]); layers run
 * strictly in order, modules within a layer run concurrently.
 */
export function groupByDependencyDepth(modules: AgentModule[]): AgentModule[][] {
  const remaining = new Map<string, AgentModule>()
  const depthById = new Map<string, number>()
  const byName = new Map<string, AgentModule>()
  for (const m of modules) {
    if (byName.has(m.name)) continue
    byName.set(m.name, m)
    remaining.set(m.name, m)
  }
  const layers: AgentModule[][] = []
  let progress = true
  while (remaining.size > 0 && progress) {
    progress = false
    const ready: AgentModule[] = []
    for (const [name, m] of remaining) {
      const deps = m.dependencies ?? []
      const readyForLayer = deps.every(d => !byName.has(d) || depthById.has(d))
      if (readyForLayer) {
        ready.push(m)
        remaining.delete(name)
      }
    }
    if (ready.length > 0) {
      const depth = layers.length
      for (const m of ready) depthById.set(m.name, depth)
      layers.push(ready)
      progress = true
    }
  }
  if (remaining.size > 0) {
    // Cyclic or unsatisfiable dependencies — refuse to boot.
    const stranded = Array.from(remaining.values()).map(m => m.name).join(', ')
    throw new Error(
      `[ModuleManager] circular module dependency detected — refusing to boot: ${stranded}`,
    )
  }
  return layers
}

export interface ModuleBootOptions {
  /**
   * v0.4.1 WS4 (ExecutionProfile): boot ONLY these module names this
   * turn. The constructed `modules` list is NOT mutated — the next
   * boot (gated or full) starts from the full set again, so per-turn
   * profile gating can never permanently lose a module. Without this
   * option the full constructed set boots (v0.4.0 behavior).
   */
  only?: string[]
}

export class ModuleManager {
  private readonly renderer: Renderer
  private readonly eventLog?: EventLog
  /** Modules array — settable for testing (boot-throw regression tests) */
  modules: AgentModule[]
  private bootResults: ModuleBootResult[] = []
  /**
   * Per-turn scoped view set by boot({only}); null = full set. All
   * in-turn hooks (iteration / toolCall / complete) iterate THIS view
   * so an unbooted module never runs its hooks. Reset on every boot().
   */
  private turnModules: AgentModule[] | null = null

  constructor(deps: ModuleManagerDeps) {
    this.modules = deps.modules
    this.renderer = deps.renderer
    this.eventLog = deps.eventLog
  }

  /** Modules active for the current turn (gated view or the full set). */
  get activeModules(): AgentModule[] {
    return this.turnModules ?? this.modules
  }

  get moduleNames(): string[] {
    return this.activeModules.map(m => m.name)
  }

  /**
   * Boot modules in topological layers (P0-7). Within a layer all
   * modules boot in parallel; between layers we strictly await.
   *
   * Criticality policy (P0-7):
   *   - critical (default): boot failure aborts the engine (throws).
   *   - best_effort: boot failure is logged and the module is dropped
   *     from this turn's active set so subsequent iteration and
   *     complete hooks skip it. On a FULL boot (no `only`) the drop
   *     mutates the constructed list (v0.4.0 behavior); on a GATED
   *     boot the drop applies to the turn view only.
   */
  async boot(bootCtx: ModuleBootContext, opts: ModuleBootOptions = {}): Promise<ModuleBootOutput> {
    this.bootResults = []
    const stranded: string[] = []
    const scoped = opts.only
      ? this.modules.filter(m => opts.only!.includes(m.name))
      : this.modules
    this.turnModules = opts.only ? scoped : null
    const layers = groupByDependencyDepth(scoped)
    for (const layer of layers) {
      // Note: async arrow (not Promise.resolve(m.boot(...))) so a
      // SYNCHRONOUS throw from boot() rejects the promise instead of
      // escaping allSettled and aborting the layer.
      const results = await Promise.allSettled(
        layer.map(async m => m.boot(bootCtx)),
      )
      results.forEach((r, i) => {
        const m = layer[i]
        if (r.status === 'fulfilled') {
          this.bootResults.push(r.value)
        } else {
          const criticality = m.criticality ?? 'critical'
          const err = r.reason instanceof Error ? r.reason.message : String(r.reason)
          if (criticality === 'best_effort') {
            this.renderer.warn(`[module:${m.name}] best-effort boot failed — dropping. (${err})`)
            this.eventLog?.append('module_flag', m.name, {
              boot_failed: true,
              criticality: 'best_effort',
              error: err,
            })
            stranded.push(m.name)
          } else {
            // critical: surface immediately. Wrap in a descriptive
            // error so callers can tell which module aborted.
            throw new Error(`[module:${m.name}] critical boot failed: ${err}`)
          }
        }
      })
    }
    if (stranded.length > 0) {
      const strandedSet = new Set(stranded)
      if (opts.only) {
        // Gated boot: drop from the per-turn view only — the
        // constructed list must survive for future turns.
        this.turnModules = scoped.filter(m => !strandedSet.has(m.name))
      } else {
        this.modules = this.modules.filter(m => !strandedSet.has(m.name))
      }
    }

    const systemPromptSections = this.bootResults.flatMap(r => r.systemPromptSections ?? [])
    const toolContextPatch = this.bootResults.reduce(
      (acc, r) => ({ ...acc, ...r.toolContextPatch }),
      {} as Partial<ToolContext>,
    )
    const tools = this.bootResults.flatMap(r => r.tools ?? [])

    return { systemPromptSections, tools, toolContextPatch }
  }

  async runIteration(params: {
    iteration: number
    messages: OpenAIMessage[]
    abortSignal: AbortSignal
    criticRequested?: boolean
  }): Promise<void> {
    const { iteration, messages, abortSignal, criticRequested } = params

    for (const module of this.activeModules) {
      if (!module.onIteration) continue
      const iterResult = await module.onIteration({
        iteration,
        messages,
        abortSignal,
        criticRequested,
      })
      if (iterResult?.injectMessage) {
        const msg = iterResult.injectMessage
        this.eventLog?.append('module_flag', module.name, {
          message: msg.slice(0, 500),
          iteration,
        })
        messages.push({ role: 'system', content: `[runtime critic] ${msg}` })
      }
    }
  }

  notifyToolCall(
    toolName: string,
    input: Record<string, unknown>,
    result: ToolResult,
    turnNumber: number,
  ): void {
    for (const module of this.activeModules) {
      module.onToolCall?.(toolName, input, result, turnNumber)
    }
  }

  /**
   * P0-1 (transactional model switch): propagate the new model to
   * every module that captures model state. Best-effort: a throwing
   * onModelChanged hook is logged but does not abort subsequent
   * modules or the runtime — losing one module's model tracking is
   * strictly better than wedging the whole engine.
   */
  notifyModelChanged(model: string): void {
    for (const module of this.activeModules) {
      if (!module.onModelChanged) continue
      try {
        module.onModelChanged(model)
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err)
        this.renderer.warn(`[module:${module.name}] onModelChanged failed: ${msg}`)
        this.eventLog?.append('module_flag', module.name, {
          on_model_changed_failed: true,
          error: msg,
        })
      }
    }
  }

  async runComplete(params: {
    cwd: string
    sessionDir?: string
    turnResult: TurnResult
    outcome?: TurnOutcome
    messages: OpenAIMessage[]
    eventLog?: EventLog
    /** v0.5.3 Final (task 2): pass the per-run context for
     *  MemoryModule.onComplete's promoter step. */
    runContext?: import('../runtime/runScopedContext.js').RunScopedRuntimeContext
    userMessage?: string
  }): Promise<void> {
    const { cwd, sessionDir, turnResult, outcome, messages, eventLog, runContext, userMessage } = params

    for (const module of this.activeModules) {
      try {
        await module.onComplete?.({
          cwd,
          sessionDir,
          turnResult,
          outcome,
          messages,
          eventLog,
          runContext,
          userMessage,
        })
      } catch {
        // module onComplete failures must never break the engine
      }
    }
  }

  dispose(): void {
    for (const module of this.modules) {
      const dispose = (module as { dispose?: () => void | Promise<void> }).dispose
      if (typeof dispose === 'function') {
        Promise.resolve(dispose.call(module)).catch(() => {
          // module dispose failures must never break engine disposal
        })
      }
    }
  }

  /**
   * P0-9: async dispose that awaits each module's disposer in turn.
   * Sync `dispose()` is fire-and-forget (kept for SIGTERM / fast-path
   * shutdown where we can't block); `disposeAsync()` is for graceful
   * shutdown where the caller can wait for MCP child processes, file
   * handles, and other async resources to be fully reaped before the
   * process exits.
   *
   * Failure isolation matches `dispose()`: a throwing disposer is
   * logged but does not abort subsequent modules.
   */
  async disposeAsync(): Promise<void> {
    for (const module of this.modules) {
      const dispose = (module as { dispose?: () => void | Promise<void> }).dispose
      if (typeof dispose !== 'function') continue
      try {
        await Promise.resolve(dispose.call(module))
      } catch {
        // module dispose failures must never break engine disposal
      }
    }
  }
}

/**
 * RevisionBinding — bind every persisted memory record to a real
 * revision state. v0.5.3 Closure (P6).
 *
 * Spec:
 *   - Git repo root / subdir / worktree: detected via
 *     `git -C <cwd> rev-parse --show-toplevel` + `--is-inside-work-tree`.
 *     The `repo` field is the canonical toplevel, NOT arbitrary cwd.
 *   - Git clean     → branch + HEAD (+ diffHash="<clean>").
 *   - Git dirty     → baseCommit + diffHash(staged+unstaged+untracked).
 *   - Non-Git       → absolute cwd + workspaceHash(manifest excluding
 *                     node_modules / .git / dist / coverage / session).
 *
 * Errors are explicit (ok / not-ok), not collapsed to "".
 */
import { execFileSync } from 'node:child_process'
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs'
import { isAbsolute, join, relative, sep } from 'node:path'
import { createHash } from 'node:crypto'
import type { RevisionBinding } from './memoryCandidate.js'

export interface RevisionBindingOptions {
  cwd?: string
  /** Disable git detection (always produce a non-git binding). */
  disableGit?: boolean
  /** Test seam: pin the result of `rev-parse --show-toplevel`. */
  forceRepoRoot?: string | null
}

export type ExecResult =
  | { ok: true; stdout: string }
  | { ok: false; reason: string }

export async function buildRevisionBinding(opts: RevisionBindingOptions = {}): Promise<RevisionBinding> {
  const cwd = opts.cwd ?? process.cwd()
  const binding: RevisionBinding = { repo: cwd, dirty: false }

  if (opts.disableGit) {
    binding.workspaceHash = workspaceHash(cwd)
    binding.dirty = true
    return binding
  }

  // Step 1: ask git for the canonical toplevel.
  const toplevel: ExecResult = opts.forceRepoRoot !== undefined
    ? safeResultFrom(opts.forceRepoRoot)
    : execGit(cwd, 'rev-parse', '--show-toplevel')
  if (!toplevel.ok) {
    // Not a git repo, OR git is missing → non-git binding.
    binding.workspaceHash = workspaceHash(cwd)
    binding.dirty = true
    return binding
  }
  // After narrowing, toplevel is {ok:true, stdout:string}.
  const toplevelPath = toplevel.stdout.trim()
  if (!toplevelPath) {
    binding.workspaceHash = workspaceHash(cwd)
    binding.dirty = true
    return binding
  }
  // `repo` is the canonical root.
  binding.repo = toplevelPath

  // Step 2: confirm we're inside that work-tree (covers subdir +
  // linked worktree cases where cwd != toplevel).
  const inside = execGit(cwd, 'rev-parse', '--is-inside-work-tree')
  if (!inside.ok || inside.stdout.trim() !== 'true') {
    // In a `.git` file pointing elsewhere — fall through with
    // non-git binding rather than fabricate.
    binding.workspaceHash = workspaceHash(cwd)
    binding.dirty = true
    return binding
  }

  // Step 3: read branch / HEAD / dirty state.
  const branch = execGit(cwd, 'rev-parse', '--abbrev-ref', 'HEAD')
  if (branch.ok) {
    const trimmed = branch.stdout.trim()
    if (trimmed && !trimmed.includes(' ')) binding.branch = trimmed
  }
  const head = execGit(cwd, 'rev-parse', 'HEAD')
  if (head.ok) {
    const trimmed = head.stdout.trim()
    if (/^[0-9a-f]{7,40}$/.test(trimmed)) binding.baseCommit = trimmed
  }

  // Step 4: dirty detection — staged + unstaged + untracked.
  const dirtyHash = computeDirtyHash(cwd)
  if (dirtyHash !== null) {
    binding.dirty = true
    binding.diffHash = dirtyHash
  } else {
    binding.dirty = false
    binding.diffHash = 'clean'
  }

  return binding
}

/** v0.5.3 Closure (P6): non-fatal `git` runner. */
function execGit(cwd: string, ...args: string[]): ExecResult {
  try {
    const stdout = execFileSync('git', args, {
      cwd,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      timeout: 2_000,
    })
    return { ok: true, stdout }
  } catch (e) {
    return { ok: false, reason: (e as Error).message ?? 'git exec failed' }
  }
}

function safeResultFrom(v: string | null): ExecResult {
  if (v === null) return { ok: false, reason: 'forceRepoRoot=null' }
  return { ok: true, stdout: v }
}

/**
 * v0.5.3 Closure (P6): dirty hash combines three sources.
 *   git diff HEAD (unstaged)
 *   git diff --cached HEAD (staged)
 *   untracked files: path + size + content hash (capped)
 *
 * Returns null when the tree is clean.
 */
function computeDirtyHash(cwd: string): string | null {
  const unstaged = execGit(cwd, 'diff', '--binary', 'HEAD')
  const staged = execGit(cwd, 'diff', '--binary', '--cached', 'HEAD')
  // Even if exec returned an error, .stdout may carry an empty
  // string — fall through and check both stdout buffers.
  const unstagedOut = unstaged.ok ? unstaged.stdout : ''
  const stagedOut = staged.ok ? staged.stdout : ''

  const untracked = listUntracked(cwd)
  if (!unstagedOut.trim() && !stagedOut.trim() && untracked.length === 0) {
    return null
  }
  const hash = createHash('sha256')
  hash.update('UNSTAGED\0')
  hash.update(unstagedOut)
  hash.update('\nSTAGED\0')
  hash.update(stagedOut)
  hash.update('\nUNTRACKED\0')
  for (const t of untracked) {
    hash.update(`${t.path}\0${t.size}\0${t.contentHash ?? 'n/a'}\n`)
  }
  return hash.digest('hex').slice(0, 16)
}

interface UntrackedEntry {
  path: string
  size: number
  contentHash?: string
}

const UNTRACKED_HASH_LIMIT = 1_048_576 // 1 MiB

/**
 * v0.5.3 Closure (P6): walk the working directory's untracked
 * files. Excludes node_modules / .git / dist / coverage / session
 * / tmp. Hashes small files inline; large files use the size
 * alone (truncated flag in the manifest entry).
 */
function listUntracked(cwd: string): UntrackedEntry[] {
  const porcelain = execGit(cwd, 'status', '--porcelain', '--untracked-files=all')
  if (!porcelain.ok) return []
  const lines = porcelain.stdout.split('\n').filter((l) => l.length >= 3)
  const EXCLUDES = new Set(['node_modules', '.git', 'dist', 'coverage', 'session', 'tmp', '.cache'])
  const out: UntrackedEntry[] = []
  for (const line of lines) {
    // Porcelain v1:  XY <path> where `??` = untracked.
    if (!line.startsWith('??')) continue
    const relPath = line.slice(3).trim()
    if (!relPath) continue
    const parts = relPath.split('/')
    if (parts.some((p) => EXCLUDES.has(p))) continue
    const abs = isAbsolute(relPath) ? relPath : join(cwd, relPath)
    try {
      const st = statSync(abs)
      if (!st.isFile()) continue
      let contentHash: string | undefined
      if (st.size <= UNTRACKED_HASH_LIMIT) {
        try {
          const buf = readFileSync(abs)
          contentHash = createHash('sha256').update(buf).digest('hex').slice(0, 16)
        } catch { /* unreadable → no content hash */ }
      }
      out.push({ path: relPath, size: st.size, contentHash })
    } catch { /* stat failed; skip */ }
  }
  return out
}

/**
 * v0.5.3 Closure (P6): non-git workspace hash. We build a SMALL
 * manifest of {relative path, size, [content hash]} over the
 * directory tree excluding noise. Same content under
 * node_modules-style churn → identical hash; content changes →
 * hash changes.
 */
function workspaceManifestHash(rootDir: string): string {
  const EXCLUDES = new Set(['node_modules', '.git', 'dist', 'coverage', 'session', 'tmp', '.cache'])
  const entries: string[] = []
  try {
    walkForManifest(rootDir, rootDir, EXCLUDES, entries, '')
  } catch { /* ignore IO errors */ }
  const hash = createHash('sha256')
  for (const line of entries.sort()) {
    hash.update(line)
    hash.update('\n')
  }
  return hash.digest('hex').slice(0, 16)
}

function walkForManifest(
  rootDir: string,
  dir: string,
  excludes: Set<string>,
  out: string[],
  rel: string,
): void {
  let entries: string[]
  try {
    entries = readdirSync(dir)
  } catch {
    return
  }
  for (const name of entries) {
    if (excludes.has(name)) continue
    const abs = join(dir, name)
    const childRel = rel ? `${rel}/${name}` : name
    let st
    try { st = statSync(abs) } catch { continue }
    if (st.isDirectory()) {
      walkForManifest(rootDir, abs, excludes, out, childRel)
    } else if (st.isFile()) {
      let contentHash = 'skipped'
      if (st.size <= UNTRACKED_HASH_LIMIT) {
        try {
          const buf = readFileSync(abs)
          contentHash = createHash('sha256').update(buf).digest('hex').slice(0, 16)
        } catch { /* unreadable */ }
      }
      out.push(`${childRel}|${st.size}|${contentHash}`)
    }
  }
}

/**
 * Non-git workspace binding: repository is the absolute cwd; the
 * identity is a content-bound manifest hash so the same workspace
 * under the same files produces the same hash, and any change
 * changes the hash.
 */
export function workspaceHash(cwd: string): string {
  return workspaceManifestHash(cwd)
}

export { isAbsolute, relative, sep }

/**
 * RuntimeCoordinator — owns the Think → Act → Observe main loop.
 *
 * Responsibilities (from architecture plan §5.1):
 *   - Boot the runtime for a turn (delegated to boot.ts)
 *   - Drive the state-machine loop (boot → check_abort → budget_check →
 *     module_iteration → llm_call → continuation_check → parse_response →
 *     tool_execution → check_abort …)
 *   - Delegate ALL concrete work to subsystems:
 *       ModelGateway   → LLM API calls
 *       ContextManager → budget + compaction
 *       ToolScheduler  → partition + execute tool calls
 *       ModuleManager  → lifecycle hooks
 *       ToolRegistry   → tool registration + lookup
 *   - Emit RunEvents at every state transition
 *   - Decide termination via TerminationPolicy
 *   - Clean up in finally (abort controller, soft-abort ownership)
 *
 * Does NOT:
 *   - Parse stream chunks directly (StreamConsumer's job)
 *   - Execute tools directly (ToolExecutor's job)
 *   - Compact context directly (ContextManager's job)
 *   - Check permissions directly (ToolExecutor's job)
 *   - Register tools directly (ToolRegistry's job, via boot.ts)
 */

