// ── memory_search — search semantic memory by keywords/tags ─────────────────

function createMemorySearchTool(semantic: SemanticMemory): Tool {
  return {
    name: 'memory_search',
    metadata: { readOnly: true, concurrencySafe: true },
    definition: {
      type: 'function',
      function: {
        name: 'memory_search',
        description: `Search long-term memory for relevant knowledge. Returns entries sorted by confidence and recency.

Use this to recall past learnings, user preferences, or project conventions that might help with the current task.`,
        parameters: {
          type: 'object',
          properties: {
            query: {
              type: 'string',
              description: 'Keywords to search for in memory content',
            },
            tags: {
              type: 'array',
              items: { type: 'string' },
              description: 'Tags to filter by (e.g. ["convention"])',
            },
            limit: {
              type: 'number',
              description: 'Max results (default: 10)',
            },
          },
        },
      },
    } satisfies ToolDefinition,

    execute(input: Record<string, unknown>): Promise<ToolResult> {
      const query = str(input.query)
      const tags = Array.isArray(input.tags)
        ? (input.tags as unknown[]).filter((t): t is string => typeof t === 'string')
        : []
      const limit = typeof input.limit === 'number' ? Math.min(input.limit, 30) : 10

      const keywords = query ? query.split(/\s+/).filter(Boolean) : undefined
      const results = semantic.search({
        keywords,
        tags: tags.length > 0 ? tags : undefined,
        limit,
      })

      if (results.length === 0) {
        return Promise.resolve({ content: 'No matching memories found.', isError: false })
      }

      const lines = results.map((e, i) => {
        const tagStr = e.tags.length > 0 ? ` [${e.tags.join(', ')}]` : ''
        return `${i + 1}. (${e.source}) ${e.content}${tagStr} (conf: ${e.confidence})`
      })

      return Promise.resolve({
        content: `Found ${results.length} memor${results.length === 1 ? 'y' : 'ies'}:\n\n${lines.join('\n')}`,
        isError: false,
      })
    },
  }
}

// ── memory_recall — recall recent episodic events ────────────────────────────

function createMemoryRecallTool(episodic: EpisodicMemory): Tool {
  return {
    name: 'memory_recall',
    metadata: { readOnly: true, concurrencySafe: true },
    definition: {
      type: 'function',
      function: {
        name: 'memory_recall',
        description: `Recall recent actions and their outcomes from episodic memory. Shows what tools were called, with what input, and what happened. Useful for reviewing what you've already tried before repeating work.`,
        parameters: {
          type: 'object',
          properties: {
            limit: {
              type: 'number',
              description: 'Number of recent episodes to recall (default: 15, max: 50)',
            },
            tool_name: {
              type: 'string',
              description: 'Filter by specific tool name (e.g. "Bash", "Read")',
            },
          },
        },
      },
    } satisfies ToolDefinition,

    execute(input: Record<string, unknown>): Promise<ToolResult> {
      const limit = typeof input.limit === 'number' ? Math.min(input.limit, 50) : 15
      const toolName = str(input.tool_name)

      const all = toolName
        ? episodic.findByTool(toolName, limit)
        : episodic.recent(limit)

      if (all.length === 0) {
        return Promise.resolve({
          content: 'No episodic memories found. Start working to build up history.',
          isError: false,
        })
      }

      const lines = all.map((e, i) => {
        const outcome = e.outcome === 'success' ? '✓' : '✗'
        return `${i + 1}. [turn ${e.turn}] ${outcome} ${e.toolName}: ${e.inputSummary.slice(0, 80)} → ${e.resultSummary.slice(0, 100)}`
      })

      return Promise.resolve({
        content: `Recalled ${all.length} episode${all.length === 1 ? '' : 's'}:\n\n${lines.join('\n')}`,
        isError: false,
      })
    },
  }
}

// ── Relevance scoring (approximates AgentOS embedding retrieval) ─────────────

/** Extract meaningful keywords from a user message.
 *  Handles both English (whitespace-split) and CJK (Chinese/Japanese/Korean)
 *  text — CJK characters are segmented into 2-char bigrams since they
 *  have no word boundaries.
 *  Exported for testing.
 */
export function extractKeywords(text: string): string[] {
  const lower = text.toLowerCase()
  // English / Latin keywords: split on whitespace + punctuation
  const latinWords = lower
    .split(/[\s,.;:!?'"\-—–()]+/)
    .filter(w => w.length > 2)
    .filter(w => !['the', 'and', 'for', 'are', 'but', 'not', 'you', 'all', 'can', 'had', 'her', 'was', 'one', 'our', 'out', 'has', 'have', 'from', 'this', 'that', 'with', 'your', 'what', 'here', 'there', 'their', 'would'].includes(w))

  // CJK keywords: extract Chinese/Japanese/Korean character runs and
  // segment into 2-char bigrams (approximates word matching for languages
  // without whitespace word boundaries)
  const cjkBigrams: string[] = []
  const cjkRuns = lower.match(/[\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]+/g) ?? []
  for (const run of cjkRuns) {
    if (run.length === 1) {
      cjkBigrams.push(run)
    } else {
      for (let i = 0; i < run.length - 1; i++) {
        cjkBigrams.push(run.slice(i, i + 2))
      }
    }
  }

  return [...latinWords, ...cjkBigrams]
}

/** Score a memory entry against keywords — higher = more relevant */
function scoreRelevance(
  entry: { content: string; tags: string[]; confidence: number },
  keywords: string[],
): number {
  if (keywords.length === 0) return 0 // no keywords → no relevance score
  const text = (entry.content + ' ' + entry.tags.join(' ')).toLowerCase()
  let matches = 0
  for (const kw of keywords) {
    if (text.includes(kw)) matches++
  }
  // Combined score: keyword coverage ratio * confidence
  const coverage = matches / keywords.length
  return coverage * entry.confidence
}

// ── MemoryModule ────────────────────────────────────────────────────────────

export class MemoryModule implements AgentModule {
  readonly name = 'memory'

  constructor(
    private semantic: SemanticMemory,
    private episodic: EpisodicMemory,
  ) {}

  /**
   * v0.5.3 P0-1: live publication of the per-turn memory
   * provenance fields. The Coordinator writes to this on every
   * turn with (repo, sourceRunId, verified) just after the runId
   * is minted. The memory_write tool's ctxProvider reads from
   * this field on every invocation so writes always carry the
   * engine-resolved provenance — never hidden input defaults.
   */
  private currentMemoryContext: MemoryToolContext = {}

  /** Coordinator hook: update the per-turn memory provenance. */
  publishMemoryContext(ctx: MemoryToolContext): void {
    this.currentMemoryContext = ctx
  }

  getMemoryContext(): MemoryToolContext {
    return this.currentMemoryContext
  }

  /**
   * v0.5.3 Final (task 2): per-runId Candidate sink. The
   * Coordinator publishes a sink closure for the current runId;
   * memory_write pushes candidates into it. Drop on close.
   */
  private readonly candidateSinks = new Map<string, (c: MemoryCandidate) => void>()

  publishCandidateSink(runId: string, sink: (c: MemoryCandidate) => void): void {
    this.candidateSinks.set(runId, sink)
  }

  closeCandidateSink(runId: string): void {
    this.candidateSinks.delete(runId)
  }

  /**
   * v0.5.3 Final (P0 issue): per-project LongTermMemory. The
   * previous instance shared `~/.ovogo/projects/default/memory/
   * longterm.jsonl` across all repos — A's memory bled into B's
   * prompt. We now re-bind the instance to a path derived from
   * the cwd at boot-time and every query carries the cwd-derived
   * repo string.
   */
  private longTerm: LongTermMemory = new LongTermMemory({
    // v0.5.3 Final: no allowCodeWithoutCommit or allowUnverified
    // shortcuts. Promotion to kind='semantic' requires the
    // RevisionBinding produced by the engine (binding.repo +
    // binding.baseCommit when present), which satisfies R3 by
    // contract.
  })
  private projectRepo: string = ''

  /**
   * v0.5.3 Final (P0 issue) + v0.5.3 Hotfix §4: bind to the
   * canonical project root. The legacy `bindToProject(cwd)`
   * contract is preserved for direct callers but engine boot now
   * threads a ProjectIdentity through and we read canonicalRoot
   * from it. A git-subdir launch therefore records and queries
   * the parent git repo's data, never the subdir.
   */
  bindToProject(cwd: string): void {
    this.projectRepo = cwd
    this.bindBackendForCwd(cwd)
  }

  /**
   * v0.5.3 Hotfix §4: bind to a fully-resolved ProjectIdentity.
   * Prefer this over `bindToProject(cwd)` for new code paths.
   */
  bindToProjectIdentity(projectIdentity: import('../core/projectIdentity.js').ProjectIdentity): void {
    this.projectRepo = projectIdentity.canonicalRoot
    this.bindBackendForCwd(projectIdentity.canonicalRoot)
  }

  /**
   * v0.5.3 Hotfix §5: lazily attach a per-project JsonlMemoryBackend
   * to the LongTermMemory instance. Called from both
   * `bindToProject` and `bindToProjectIdentity`. The constructor
   * no longer creates a default JSONL file — every project gets
   * its own path derived from `defaultMemoryPath(canonicalRoot)`.
   * Tests can pin the file path via `OVOGO_HOME` / `HOME` env or
   * by calling `setLongTermBackendPath` before boot.
   */
  private bindBackendForCwd(cwd: string): void {
    const path = defaultMemoryPath(cwd)
    this.currentLongTermPath = path
    // Rebind unconditionally. Each boot re-attaches the per-project
    // JSONL file. Multiple boots in the same project rewrite the
    // same path — file state is preserved across boots because
    // bindBackend replaces the backend reference, not the file.
    this.longTerm.bindBackend(new JsonlMemoryBackend(path))
  }

  /** v0.5.3 Hotfix §5: current project's actual backend path. */
  private currentLongTermPath: string = ''

  /** Repo filter — used by every read query below. */
  private repoFilter(): string {
    return this.projectRepo
  }

  /** Override the per-process LongTermMemory instance (tests). */
  setLongTermMemory(ltm: LongTermMemory): void {
    this.longTerm = ltm
  }

  /**
   * v0.5.3 Hotfix §5: returns the per-project JSONL file path
   * for the currently-bound project. Empty string before bind.
   */
  getLongTermMemoryPath(): string {
    return this.currentLongTermPath || defaultMemoryPath(this.projectRepo)
  }

  boot(ctx: ModuleBootContext): ModuleBootResult {
    // v0.5.3 Final (task 5): memory retrieval reads LongTermMemory
    // directly. SemanticMemory is kept for back-compat reads only
    // (until migration; see migrateSemanticToLongTerm below).
    let section = ''
    // v0.5.3 Hotfix §4: bind to the resolved ProjectIdentity's
    // canonicalRoot, NOT ctx.cwd. Git-subdir launches must use
    // the parent git repo's data so memory_search can find
    // records written from the project root.
    if (ctx.projectIdentity) {
      this.bindToProjectIdentity(ctx.projectIdentity)
    } else {
      this.bindToProject(ctx.cwd)
    }
    try {
      const ltmRecords = this.longTerm.query({
        kind: 'semantic',
        verified: true,
        // v0.5.3 Final (P0 issue): repo filter is MANDATORY. Without
        // it, A's memory bleeds into B's prompt.
        repo: this.repoFilter(),
        limit: 10,
      })
      if (ltmRecords.length > 0 && ctx.userMessage) {
        const keywords = extractKeywords(ctx.userMessage)
        const scored = ltmRecords
          .map((r: { content: string; tags: string[]; confidence: number }) => ({
            entry: { content: r.content, tags: r.tags, confidence: r.confidence },
            score: scoreRelevance({ content: r.content, tags: r.tags, confidence: r.confidence }, keywords),
          }))
          .filter((x: { score: number }) => x.score > 0)
          .sort((a: { score: number }, b: { score: number }) => b.score - a.score)
          .slice(0, 10)
        if (scored.length > 0) {
          const lines = scored.map(({ entry: e, score }: { entry: { content: string; tags: string[]; confidence: number }; score: number }) => {
            const s = score.toFixed(2)
            const tags = e.tags.length > 0 ? ` [${e.tags.join(', ')}]` : ''
            return `- (${s}) ${e.content}${tags}`
          })
          section = `## Memory — Relevant Knowledge (LongTermMemory top-K)\n\nKeywords: ${keywords.slice(0, 10).join(', ')}\n\n${lines.join('\n')}`
        }
      }
    } catch { /* if LongTermMemory read fails, fall back silently — never block boot */ }

    // Fallback: build the legacy semantic section only if LongTermMemory yielded nothing
    if (!section) {
      const memoryDir = getMemoryDir(ctx.cwd)
      section = buildMemorySystemSection(memoryDir)
    }

    return {
      systemPromptSections: section ? [section] : [],
      toolContextPatch: {
        semanticMemory: this.semantic,
        episodicMemory: this.episodic,
      },
      tools: [
        // v0.5.3 Final (task 2): tool pushes Candidate into the
        // per-run sink, NOT to LongTermMemory.
        createMemoryWriteTool(
          this.semantic,
          () => this.currentMemoryContext,
          (cand: MemoryCandidate) => {
            const sink = this.candidateSinks.get(cand.runId)
            if (!sink) return false
            sink(cand)
            return true
          },
        ),
        // v0.5.3 Final (task 5): memory_search queries LongTermMemory
        // directly — semantic mirror removed from production reads.
        createMemorySearchToolLTM(this.longTerm, () => this.repoFilter()),
        createMemoryRecallTool(this.episodic),
      ],
    }
  }

  /**
   * v0.5.3 Final (task 2): promote this run's MemoryCandidates.
   * Called from the Coordinator right after evaluateCompletion().
   * Reads candidates from the per-run RunScopedRuntimeContext and
   * promotes each one based on the completion verdict.
   *
   * Also closes the per-run candidate sink so a re-run does not
   * inherit closures from the previous run.
   */
  async onComplete(ctx: ModuleRunContext): Promise<void> {
    // Close the sink even if we do not have a runContext.
    if (ctx.outcome?.runId) {
      // Close at the end — no further candidates will land.
      this.closeCandidateSink(ctx.outcome.runId)
    }
    if (!ctx.outcome || !ctx.cwd) return

    const runContext = (ctx as unknown as { runContext?: { memoryCandidates?: MemoryCandidate[]; userMessage?: string } }).runContext
    const candidates = runContext?.memoryCandidates ?? []
    const userMessage = runContext?.userMessage ?? ''

    if (candidates.length === 0) return

    // v0.5.3 Final (task 3): build a real RevisionBinding from the
    // workspace. Non-git fallback returns workspaceHash, never a
    // fabricated commit.
    const binding: RevisionBinding = await buildRevisionBinding({ cwd: ctx.cwd })

    // v0.5.3 Hotfix §6: emit MEMORY_PROMOTION_STARTED before
    // decidePromotion runs. The audit trail can prove the
    // promoter actually ran (vs being bypassed).
    ctx.eventLog?.append('memory_promotion_started', 'memory', {
      runId: ctx.outcome.runId,
      candidateCount: candidates.length,
    })

    const decision = decidePromotion({
      candidates,
      outcome: ctx.outcome,
      userMessage,
      revision: binding,
      // v0.5.5 §2+§3: thread the per-run registries. MemoryModule
      // pulls them from the runContext the Coordinator passed via
      // ModuleRunContext.runContext. Both objects are required
      // for tool_observed validation (Registry) and verification
      // ref resolution (EvidenceStore).
      toolCallRegistry: (runContext as unknown as { toolCallRegistry?: Map<string, { resultText: string; truncated: boolean; isError: boolean }> } | undefined)?.toolCallRegistry,
      projectIdentity: (runContext as unknown as { projectIdentity?: { canonicalRoot: string } } | undefined)?.projectIdentity,
      evidenceStore: (runContext as unknown as { evidence?: { get(id: string): { status: string; createdAt: number } | undefined } } | undefined)?.evidence,
    })

    for (const drop of decision.dropped) {
      ctx.eventLog?.append('memory_promotion_rejected', 'memory', {
        runId: ctx.outcome.runId,
        candidateId: drop.candidateId,
        reason: drop.reason,
      })
    }
    for (const promo of [...decision.successPromotions, ...decision.failurePromotions]) {
      try {
        this.longTerm.record(promo.memoryInput)
        ctx.eventLog?.append('memory_promotion_decided', 'memory', {
          runId: ctx.outcome.runId,
          candidateId: promo.candidate.id,
          kind: promo.memoryInput.kind,
          verified: promo.memoryInput.verified,
          origin: promo.memoryInput.origin,
        })
      } catch (err) {
        // If a single record is rejected (e.g. commit-binding still
        // missing for an unexpected content shape), drop and
        // continue — we do not let one bad candidate break the run.
        ctx.eventLog?.append('memory_promotion_rejected', 'memory', {
          runId: ctx.outcome.runId,
          candidateId: promo.candidate.id,
          reason: (err as Error).message,
        })
      }
    }
  }

  onToolCall(
    toolName: string,
    input: Record<string, unknown>,
    result: { content: string; isError: boolean },
    turnNumber: number,
  ): void {
    // Don't track memory tool calls themselves (avoid noise)
    if (toolName.startsWith('memory_')) return

    // Record both successes and failures (AgentOS pattern — learn from mistakes)
    this.episodic.write({
      turn: turnNumber,
      toolName,
      inputSummary: JSON.stringify(input).slice(0, 200),
      resultSummary: result.content.slice(0, 300),
      outcome: result.isError ? 'failure' as const : 'success' as const,
      timestamp: new Date().toISOString(),
    })
  }
}

// ── LongTermMemory-backed search (replaces the semantic mirror) ──────────
function createMemorySearchToolLTM(ltm: LongTermMemory, getRepo: () => string): Tool {
  return {
    name: 'memory_search',
    metadata: { readOnly: true, concurrencySafe: true },
    definition: {
      type: 'function',
      function: {
        name: 'memory_search',
        description: 'Search long-term memory by keywords/tags. Returns verified entries sorted by confidence and recency.',
        parameters: {
          type: 'object',
          properties: {
            query: { type: 'string', description: 'Keywords to search for in memory content' },
            tags: { type: 'array', items: { type: 'string' }, description: 'Tags to filter by' },
            limit: { type: 'number', description: 'Max results (default: 10)' },
          },
        },
      },
    } satisfies ToolDefinition,
    execute(input: Record<string, unknown>): Promise<ToolResult> {
      const query = str(input.query)
      const tags = Array.isArray(input.tags)
        ? (input.tags as unknown[]).filter((t): t is string => typeof t === 'string')
        : []
      const limit = typeof input.limit === 'number' ? Math.min(input.limit, 30) : 10
      const records = ltm.query({
        kind: 'semantic',
        verified: true,
        // v0.5.3 Final (P0 issue): per-project isolation. A's memory
        // does NOT leak into B's prompt / search results.
        repo: getRepo(),
        fullText: query || undefined,
        tag: tags[0],
        limit,
      })
      if (records.length === 0) {
        return Promise.resolve({ content: 'No matching memories found.', isError: false })
      }
      const lines = records.map((r, i) => {
        const tagStr = r.tags.length > 0 ? ` [${r.tags.join(', ')}]` : ''
        return `${i + 1}. (${r.kind}) ${r.content}${tagStr} (conf: ${r.confidence})`
      })
      return Promise.resolve({
        content: `Found ${records.length} memor${records.length === 1 ? 'y' : 'ies'}:\n\n${lines.join('\n')}`,
        isError: false,
      })
    },
  }
}

// (RevisionBinding comes from src/core/revisionBinding.ts — the
// stub above was deleted; the real implementation lives in that
// module. Keeping this comment as a breadcrumb so future readers
// understand why neither `workspaceHash` nor `buildRevisionBinding`
// are defined here.)

/**
 * WorkspaceWatcherModule — turns the R8 chokidar-based WorkspaceWatcher
 * into a real runtime capability (P2.2 follow-up).
 *
 * Before: `src/core/workspaceWatcher.ts` was an isolated module with no
 * runtime caller. chokidar was wired into the watcher but never invoked.
 *
 * After: this module starts the watcher on boot, watches the cwd and
 * `~/.ovogo/` for changes, and:
 *   1. Invalidates the toolSearch in-memory cache so any new
 *      `search_extra_tools` query reflects the latest tool definitions.
 *   2. Records each change to the EventLog so `/trace` and the
 *      post-mortem know the workspace was mutated mid-session.
 *   3. Optionally injects a system-reminder on the next iteration
 *      (`workspace_changed`) so the LLM knows what is on disk.
 *
 * The module is best-effort — if chokidar fails to start (e.g. EPERM
 * on a directory), the engine still boots and proceeds without it.
 */

import { existsSync } from 'node:fs'
import { join } from 'node:path'
import { homedir } from 'node:os'

import type { AgentModule, ModuleBootContext, ModuleBootResult, ModuleIterationContext, ModuleIterationResult, ModuleRunContext } from '../core/module.js'
import { WorkspaceWatcher, type WorkspaceChange } from '../core/workspaceWatcher.js'
import { clearToolIndexCache } from '../core/toolSearch.js'
import { RepoStatsService } from '../core/repoStats.js'

const SKILL_DIRS = [
  join(homedir(), '.ovogo', 'skills'),
  join(homedir(), '.ovolv999', 'knowledge'),
]

function collectWatchRoots(cwd: string): string[] {
  const roots: string[] = [cwd]
  for (const dir of SKILL_DIRS) {
    if (existsSync(dir)) roots.push(dir)
  }
  return roots
}

export class WorkspaceWatcherModule implements AgentModule {
  readonly name = 'workspace_watcher'
  readonly criticality = 'best_effort' as const

  private watcher: WorkspaceWatcher | null = null
  private lastChanges: WorkspaceChange[] = []
  private lastChangeAt = 0
  private injectedForRun = false
  /** v0.5.3 (P0.2): shared RepoStatsService instance. Engine is
   *  REQUIRED to pass this in via the constructor; if omitted the
   *  module logs a warning AND uses a degraded local instance so
   *  the cache invalidation contract is visible to callers. */
  private readonly repoStats: RepoStatsService

  constructor(repoStats?: RepoStatsService) {
    if (repoStats) {
      this.repoStats = repoStats
    } else {
      // Degraded mode — Engine forgot to inject. Module still works
      // but the Router never sees invalidation events.
      process.stderr.write(
        '[workspaceWatcher] WARNING: no RepoStatsService injected; ' +
          'cache invalidation will not reach the Router.\n',
      )
      this.repoStats = new RepoStatsService()
    }
  }

  async boot(ctx: ModuleBootContext): Promise<ModuleBootResult> {
    // v0.5.3 (P0.2): pull the shared RepoStatsService from the boot
    // context. Engine is the SOLE constructor; if the field is missing
    // the constructor's warning has already been emitted.
    const shared = ctx.sharedServices?.repoStats
    if (shared && shared !== this.repoStats) {
      // The constructor's `this.repoStats` may have been a degraded
      // private instance; replace it with the shared one now that
      // the Engine has had a chance to inject it.
      ;(this as unknown as { repoStats: RepoStatsService }).repoStats = shared
    }

    const roots = collectWatchRoots(ctx.cwd)
    this.watcher = new WorkspaceWatcher({
      rootDir: roots[0],
      pollIntervalMs: 50,
      debounceMs: 30,
      onChange: (change) => this.recordChange(change),
    })
    this.watcher.start()

    // Also watch external roots (user skills, knowledge base). Each gets
    // its own chokidar instance since chokidar.watch() takes one root.
    for (const root of roots.slice(1)) {
      try {
        const w = new WorkspaceWatcher({
          rootDir: root,
          pollIntervalMs: 50,
          debounceMs: 30,
          onChange: (change) => this.recordChange(change),
        })
        w.start()
        this.attachedWatchers.push(w)
      } catch { /* best-effort */ }
    }

    return {}
  }

  private attachedWatchers: WorkspaceWatcher[] = []

  private recordChange(change: WorkspaceChange): void {
    this.lastChanges.push(change)
    if (this.lastChanges.length > 50) {
      this.lastChanges.splice(0, this.lastChanges.length - 50)
    }
    this.lastChangeAt = Date.now()
    // real cache invalidation: next search_extra_tools sees fresh tool defs
    clearToolIndexCache()
    // v0.5.2 (Stage 2.2): invalidate the cached repoFileCount so the
    // next Router signal collection re-walks the cwd. We use a
    // per-process singleton (RepoStatsService is constructed once
    // per Engine); the watcher can fire from many roots but the
    // service only walks the cwd on the next snapshot() call.
    this.repoStats.invalidate()
  }

  /**
   * Called at the top of each engine loop iteration. If the workspace
   * changed since the last iteration, inject a system reminder so the
   * LLM knows the file system is different from what it last saw.
   */
  onIteration(_ctx: ModuleIterationContext): void | Promise<ModuleIterationResult | void> {
    if (this.injectedForRun) return
    if (this.lastChangeAt === 0) return
    if (this.lastChanges.length === 0) return

    const sample = this.lastChanges.slice(-5).map((c) => `${c.kind}: ${c.path}`).join(', ')
    this.injectedForRun = true
    return Promise.resolve({
      injectMessage: `[system-reminder] workspace files changed since last iteration: ${sample}. ` +
        `On-disk contents may differ from earlier context — re-read before quoting.`,
    })
  }

  onComplete(ctx: ModuleRunContext): void {
    if (this.lastChanges.length === 0) return
    if (ctx.eventLog) {
      ctx.eventLog.append(
        'workspace_change',
        'workspace_watcher',
        {
          changes: this.lastChanges.slice(),
          reason: ctx.turnResult?.reason,
          at: this.lastChangeAt,
          watchedRoots: this.watcher ? 1 + this.attachedWatchers.length : 0,
        },
      )
    }
  }

  async dispose(): Promise<void> {
    if (this.watcher) {
      this.watcher.stop()
      this.watcher = null
    }
    for (const w of this.attachedWatchers) {
      w.stop()
    }
    this.attachedWatchers = []
  }

  /** v0.5.3 (P0.2): test seams. */
  getRepoStats(): RepoStatsService {
    return this.repoStats
  }

  simulateChangeForTest(change: WorkspaceChange): void {
    this.recordChange(change)
  }
}

/**
 * TaskPlan tool (adaptive runtime contract Phase 3) — lets the model decompose a task
 * into the TaskGraph and walk nodes through their lifecycle. This is
 * what makes the TaskGraph LIVE in a real run: the model plans → adds
 * nodes → the CompletionContract gate then refuses 'completed' until
 * every node is terminal.
 *
 * v0.3.2 (run-scoped runtime contract §Phase 2): the tool no longer holds a fixed
 * TaskGraph. It receives a TaskGraphResolver and resolves the graph
 * for the current runId from ToolContext.execution.runId. Removing
 * the constructor-injected graph is the single source-identity fix
 * for TaskGraph pollution.
 *
 * Actions: add | start | update | begin_verification | complete |
 *          fail | block | unblock | retry | cancel | attach_artifact | list
 * The tool is a thin wrapper over the TaskGraph engine (src/core/runtime/
 * taskGraph.ts) — all invariants (dep resolution, acceptance gate,
 * cycle rejection, retry caps) live there.
 */

import type { Tool, ToolContext, ToolDefinition, ToolResult } from '../core/types.js'
import { str } from '../core/strings.js'
import type { TaskGraph } from '../core/runtime/taskGraph.js'
import type { TaskGraphResolver } from './taskGraphResolver.js'
import type { EvidenceStore } from '../core/runtime/evidence.js'

export interface EvidenceResolver {
  resolve(runId: string): EvidenceStore
}

export class TaskPlanTool implements Tool {
  name = 'TaskPlan'
  metadata = { readOnly: false, concurrencySafe: false, mutatesState: true }
  definition: ToolDefinition = {
    type: 'function',
    function: {
      name: 'TaskPlan',
      description:
        'Decompose a non-trivial task into a dependency-ordered plan and track each piece to completion. Use for medium/large tasks only — do NOT create a graph for trivial one-step work. ' +
        'The runtime refuses to mark the overall task completed while any node is unfinished or failed. ' +
        'IMPORTANT: You CANNOT declare criteria satisfied by text. You must record real evidence (command results) via record_evidence, then call complete_node — the system verifies automatically. ' +
        'Actions: "add", "start", "update", "begin_verification", "record_evidence", "complete_node", "fail", "block", "unblock", "retry", "cancel", "attach_artifact", "list".',
      parameters: {
        type: 'object',
        properties: {
          action: {
            type: 'string',
            enum: [
              'add', 'start', 'update', 'begin_verification', 'record_evidence',
              'complete_node', 'fail', 'block', 'unblock', 'retry', 'cancel', 'attach_artifact', 'list',
            ],
            description: 'Operation to perform',
          },
          id: { type: 'string', description: 'Node id (for add this is the new node id; for others, the target)' },
          title: { type: 'string', description: 'Short title (add/update only)' },
          description: { type: 'string', description: 'What this node accomplishes (add/update only)' },
          dependencies: { type: 'array', items: { type: 'string' }, description: 'Node ids that must complete before this one (add only)' },
          acceptanceCriteria: { type: 'array', items: { type: 'string' }, description: 'Criteria that must hold to complete this node (add only)' },
          resourceClaims: { type: 'array', items: { type: 'string' }, description: 'Resource keys this node touches' },
          preferredRole: { type: 'string', description: 'Hint role for sub-agent delegation' },
          reason: { type: 'string', description: 'Failure / block / cancel reason' },
          artifact: { type: 'string', description: 'Artifact name to attach (attach_artifact only)' },
          evidence_kind: { type: 'string', enum: ['command_result', 'test_result', 'build_result', 'file_change', 'artifact', 'analysis_result'], description: 'Type of evidence (record_evidence only)' },
          evidence_summary: { type: 'string', description: 'Short summary of what the evidence shows (record_evidence only)' },
          evidence_command: { type: 'string', description: 'The command that was run (record_evidence only)' },
          evidence_exit_code: { type: 'number', description: 'Exit code of the command (record_evidence only)' },
          evidence_criterion_id: { type: 'string', description: 'Which acceptance criterion this evidence supports (record_evidence only)' },
          // v0.5.3 P0-4: TaskImpact fields are now exposed to the
          // LLM in the tool schema. Without these the model could
          // not declare scope/affects_public_interface/etc. — they
          // only existed on the in-memory node, with no path in
          // for the model to set them. The Router reads the same
          // fields to escalate code that crosses boundaries.
          //
          // v0.5.3 Final (task 1): impact_scope enum is the SINGLE
          // vocabulary — sourced from src/core/taskImpact.ts. Any
          // drift between schema enum and parser enum is now caught
          // by a runtime-truth round-trip check.
          impact_scope: {
            type: 'string',
            enum: ['local', 'module', 'cross-module', 'repository'],
            description: 'How far does this change reach? local = single file/module; module = several files in one module; cross-module = multiple modules; repository = whole repo.',
          },
          affects_public_interface: {
            type: 'boolean',
            description: 'True iff this change modifies an exported function signature, public type, or HTTP/RPC contract. Router uses this to prefer long-context models.',
          },
          changes_configuration: {
            type: 'boolean',
            description: 'True iff this change writes to a config file (.json/.yaml/.toml/.env schema, package.json, etc). Router treats config edits as risk-bearing.',
          },
          requires_root_cause: {
            type: 'boolean',
            description: 'True iff this change fixes a bug rather than adding a feature. Router insists on root-cause reasoning for these.',
          },
          estimated_files: {
            type: 'number',
            minimum: 0,
            description: 'Best-guess count of files this change will touch. 0 = unknown; ≥ 1 = concrete estimate. Router uses this for budget + complexity heuristics.',
          },
        },
        required: ['action'],
      },
    },
  }

  constructor(
    private readonly resolver?: TaskGraphResolver,
    private readonly evidenceResolver?: EvidenceResolver,
  ) {}

  // eslint-disable-next-line @typescript-eslint/require-await
  async execute(input: Record<string, unknown>, ctx: ToolContext): Promise<ToolResult> {
    const runId = ctx.execution?.runId
    if (!this.resolver) {
      return err('TaskPlan unavailable: no resolver wired on this engine.')
    }
    if (!runId) {
      return err('TaskPlan unavailable: no runId in ToolContext.execution.')
    }
    let g: TaskGraph
    try {
      g = this.resolver.resolve(runId)
    } catch (e) {
      return err(`TaskPlan unavailable: ${(e as Error).message}`)
    }
    // v0.3.5: resolve the per-run EvidenceStore
    let evidence: EvidenceStore | undefined
    try {
      evidence = this.evidenceResolver?.resolve(runId)
    } catch { /* evidence optional in tests */ }

    const action = str(input.action)
    try {
      switch (action) {
        case 'add': {
          const id = str(input.id)
          if (!id) return err('id is required for add')
          if (g.has(id)) return err(`node "${id}" already exists`)
          // v0.5.3 (P1.7): validate structured impact fields. Illegal
          // values are rejected (NOT silently coerced). Legacy callers
          // that omit impact still work — impact is optional.
          const impactResult = parseImpact(input.impact_scope, {
            affects_public_interface: input.affects_public_interface,
            changes_configuration: input.changes_configuration,
            requires_root_cause: input.requires_root_cause,
            estimated_files: input.estimated_files,
          })
          if (impactResult.error) return err(`invalid impact: ${impactResult.error}`)
          g.addNode({
            id,
            title: str(input.title, id),
            description: str(input.description),
            dependencies: asStrArr(input.dependencies),
            acceptanceCriteria: asStrArr(input.acceptanceCriteria),
            resourceClaims: asStrArr(input.resourceClaims),
            preferredRole: str(input.preferredRole) || undefined,
            retryPolicy: { maxAttempts: 2 },
            impact: impactResult.impact,
          })
          return ok(`Added node "${id}". ${renderGraph(g)}`)
        }
        case 'start': {
          const id = str(input.id)
          g.start(id)
          return ok(`Started "${id}". ${renderGraph(g)}`)
        }
        case 'update': {
          const id = str(input.id)
          if (!g.has(id)) return err(`node "${id}" does not exist`)
          const n = g.get(id)!
          if (n.status !== 'pending') return err(`cannot update node "${id}" in status ${n.status}`)
          if (input.title !== undefined) n.title = str(input.title, n.title)
          if (input.description !== undefined) n.description = str(input.description, n.description)
          // v0.5.3 (P1.7): impact can be updated too — same
          // validation as add.
          if (input.impact_scope !== undefined) {
            const impactResult = parseImpact(input.impact_scope, {
              affects_public_interface: input.affects_public_interface,
              changes_configuration: input.changes_configuration,
              requires_root_cause: input.requires_root_cause,
              estimated_files: input.estimated_files,
            })
            if (impactResult.error) return err(`invalid impact: ${impactResult.error}`)
            n.impact = impactResult.impact
          }
          return ok(`Updated "${id}".`)
        }
        case 'begin_verification': {
          const id = str(input.id)
          g.markVerifying(id)
          return ok(`"${id}" → verifying.`)
        }
        case 'record_evidence': {
          const id = str(input.id)
          if (!g.has(id)) return err(`node "${id}" does not exist`)
          if (!evidence) return err('EvidenceStore not available on this engine.')
          const kind = str(input.evidence_kind) as 'command_result' | 'test_result' | 'build_result' | 'file_change' | 'artifact' | 'analysis_result'
          if (!kind) return err('evidence_kind is required for record_evidence')
          const ev = evidence.record({
            runId,
            nodeId: id,
            criterionId: str(input.evidence_criterion_id) || undefined,
            kind,
            summary: str(input.evidence_summary, '(no summary)'),
            source: 'tool_execution',
            command: str(input.evidence_command) || undefined,
            exitCode: typeof input.evidence_exit_code === 'number' ? input.evidence_exit_code : undefined,
          })
          return ok(`Recorded evidence ${ev.id} (${kind}) for "${id}". Exit: ${ev.exitCode ?? 'n/a'}`)
        }
        case 'complete_node': {
          const id = str(input.id)
          if (!g.has(id)) return err(`node "${id}" does not exist`)
          const node = g.get(id)!
          // v0.3.5: system computes criterion satisfaction from evidence.
          // The model CANNOT pass satisfiedCriteria — the system decides.
          if (evidence && node.acceptanceCriteria.length > 0) {
            const criteria = node.acceptanceCriteria.map((desc, i) => ({ id: `${id}::${i}`, description: desc }))
            const states = evidence.computeAllCriteria(id, criteria)
            const unsatisfied = states.filter((s) => s.status !== 'satisfied' && s.status !== 'waived')
            if (unsatisfied.length > 0) {
              const detail = unsatisfied.map((s) => `  ✗ [${s.status}] ${s.description}`).join('\n')
              return err(`Cannot complete "${id}" — ${unsatisfied.length} criteria not satisfied:\n${detail}\nRecord evidence (record_evidence) for each criterion.`)
            }
            // All satisfied — complete with evidence-backed proof
            g.complete(id)
          } else {
            // No criteria or no evidence store — fall back to direct complete
            g.complete(id)
          }
          const n = g.get(id)!
          return ok(n.status === 'completed'
            ? `Completed "${id}" (evidence-verified). ${renderGraph(g)}`
            : `Could not complete "${id}" → ${n.status}: ${n.failReason ?? ''}`)
        }
        case 'fail': {
          g.fail(str(input.id), str(input.reason, 'failed'))
          return ok(`Marked "${str(input.id)}" failed. ${renderGraph(g)}`)
        }
        case 'block': {
          g.block(str(input.id), str(input.reason, 'blocked'))
          return ok(`Marked "${str(input.id)}" blocked. ${renderGraph(g)}`)
        }
        case 'unblock': {
          g.unblock(str(input.id))
          return ok(`Unblocked "${str(input.id)}". ${renderGraph(g)}`)
        }
        case 'cancel': {
          const id = str(input.id)
          g.cancel(id, str(input.reason, 'cancelled'))
          return ok(`Cancelled "${id}". ${renderGraph(g)}`)
        }
        case 'attach_artifact': {
          const id = str(input.id)
          const art = str(input.artifact)
          if (!art) return err('artifact is required for attach_artifact')
          g.attachArtifact(id, art)
          return ok(`Attached "${art}" to "${id}".`)
        }
        case 'retry': {
          g.retry(str(input.id))
          const n = g.get(str(input.id))!
          return ok(`Node "${str(input.id)}" → ${n.status}.`)
        }
        case 'list':
          return ok(renderGraph(g))
        default:
          return err(`unknown action "${action}"`)
      }
    } catch (e) {
      return err((e as Error).message)
    }
  }
}

function renderGraph(g: TaskGraph): string {
  const s = g.snapshot().summary
  const head = `Plan: ${s.completed}/${s.total} done · ${s.failed} failed · ${s.blocked} blocked · ${s.running} running · ${s.ready} ready · ${s.pending} pending`
  const lines = g.snapshot().nodes.map((n) => {
    const deps = n.dependencies.length ? ` ←[${n.dependencies.join(',')}]` : ''
    const flag = n.status === 'blocked' ? ` ⚠${n.blockReason ? ' ' + n.blockReason : ''}`
      : n.status === 'failed' ? ` ✗${n.failReason ? ' ' + n.failReason : ''}` : ''
    const impact = n.impact
      ? ` impact=${n.impact.scope}${n.impact.affectsPublicInterface ? '/public' : ''}${n.impact.changesConfiguration ? '/config' : ''}${n.impact.requiresRootCause ? '/rootcause' : ''}`
      : ''
    return `  [${n.status}] ${n.title}${deps}${flag}${impact}`
  })
  return [head, ...lines].join('\n')
}

function asStrArr(v: unknown): string[] {
  return Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : []
}

/** v0.5.3 (P1.7): validate the structured impact payload. Returns
 *  the parsed TaskImpact on success or `{error: string}` when any
 *  field is illegal. Legacy callers that omit impact entirely
 *  get `{impact: undefined}` — the Router then falls back to
 *  keyword heuristics.
 *
 *  v0.5.3 Final (task 1): the vocabulary is sourced from
 *  src/core/taskImpact.ts. Drift between schema enum and parser
 *  enum is now a compile-time / round-trip-time failure. */
import {
  TASK_IMPACT_SCOPES,
  isTaskImpactScope,
  type TaskImpactScope,
  type TaskImpact as TaskImpactCanonical,
} from '../core/taskImpact.js'

function parseImpact(
  scope: unknown,
  flags: {
    affects_public_interface?: unknown
    changes_configuration?: unknown
    requires_root_cause?: unknown
    estimated_files?: unknown
  },
): { impact?: TaskImpactCanonical; error?: string } {
  // Legacy path: no impact supplied at all.
  if (scope === undefined && flags.affects_public_interface === undefined &&
      flags.changes_configuration === undefined && flags.requires_root_cause === undefined &&
      flags.estimated_files === undefined) {
    return { impact: undefined }
  }
  let scopeVal: TaskImpactScope | null = null
  if (typeof scope !== 'string') {
    return { error: `impact_scope must be a string (one of ${TASK_IMPACT_SCOPES.join('|')})` }
  }
  if (!isTaskImpactScope(scope)) {
    return { error: `impact_scope "${scope}" is invalid; expected one of ${TASK_IMPACT_SCOPES.join('|')}` }
  }
  scopeVal = scope
  const apf = flags.affects_public_interface
  if (apf !== undefined && typeof apf !== 'boolean') return { error: 'affects_public_interface must be boolean' }
  const cc = flags.changes_configuration
  if (cc !== undefined && typeof cc !== 'boolean') return { error: 'changes_configuration must be boolean' }
  const rc = flags.requires_root_cause
  if (rc !== undefined && typeof rc !== 'boolean') return { error: 'requires_root_cause must be boolean' }
  const ef = flags.estimated_files
  let efVal: number = 0
  if (ef !== undefined) {
    if (typeof ef !== 'number' || ef < 0 || !Number.isInteger(ef)) {
      return { error: 'estimated_files must be a non-negative integer' }
    }
    efVal = ef
  }
  return {
    impact: {
      scope: scopeVal,
      affectsPublicInterface: apf === true,
      changesConfiguration: cc === true,
      requiresRootCause: rc === true,
      estimatedFiles: efVal,
    },
  }
}
function ok(content: string): ToolResult {
  return { content, isError: false }
}
function err(content: string): ToolResult {
  return { content, isError: true }
}

import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { mkdtempSync, writeFileSync, rmSync, existsSync, mkdirSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import {
  getSessionsDir,
  createSessionId,
  saveMeta,
  loadMeta,
  appendTurn,
  loadTurns,
  listSessions,
  deleteSession,
  getSessionStats,
  MAX_TURNS_PER_SESSION,
  type SessionMeta,
  type PersistedTurn,
} from '../../../src/core/daemon/sessionStore.js'

describe('sessionStore', () => {
  let tmpHome: string
  let oldHome: string | undefined

  beforeEach(() => {
    tmpHome = mkdtempSync(join(tmpdir(), 'ovolv999-session-'))
    oldHome = process.env.HOME
    process.env.HOME = tmpHome
  })
  afterEach(() => {
    process.env.HOME = oldHome
    rmSync(tmpHome, { recursive: true, force: true })
  })

  it('creates sessions dir on demand', () => {
    saveMeta({
      sessionId: 'abc',
      goal: 'test',
      cwd: '/tmp',
      startedAt: Date.now(),
      status: 'running',
    })
    expect(existsSync(getSessionsDir())).toBe(true)
  })

  it('round-trips meta via saveMeta/loadMeta', () => {
    const meta: SessionMeta = {
      sessionId: 's-1',
      goal: 'refactor',
      cwd: '/home/u/proj',
      startedAt: Date.now(),
      status: 'idle',
      model: 'claude-sonnet-4-6',
    }
    saveMeta(meta)
    const loaded = loadMeta('s-1')
    expect(loaded).toEqual(meta)
  })

  it('returns null for missing meta', () => {
    expect(loadMeta('does-not-exist')).toBeNull()
  })

  it('appends and loads turns', () => {
    const id = createSessionId()
    saveMeta({ sessionId: id, goal: 'g', cwd: '/tmp', startedAt: Date.now(), status: 'running' })
    const turns: PersistedTurn[] = [
      { ts: 1, user: 'hi', assistant: 'hello', status: 'completed' },
      { ts: 2, user: 'how are you?', assistant: 'fine', status: 'completed', tokens: { input: 10, output: 20 } },
    ]
    for (const turn of turns) appendTurn(id, turn)
    const loaded = loadTurns(id)
    expect(loaded).toEqual(turns)
  })

  it('skips corrupted JSONL lines', () => {
    const id = createSessionId()
    saveMeta({ sessionId: id, goal: 'g', cwd: '/tmp', startedAt: Date.now(), status: 'running' })
    appendTurn(id, { ts: 1, user: 'good', assistant: 'bad', status: 'completed' })
    const path = join(getSessionsDir(), `${id}.turns.jsonl`)
    writeFileSync(path, '{ broken json\n', { flag: 'a' })
    appendTurn(id, { ts: 2, user: 'second', assistant: 'reply', status: 'completed' })
    const loaded = loadTurns(id)
    expect(loaded.length).toBe(2)
    expect(loaded[0]?.user).toBe('good')
    expect(loaded[1]?.user).toBe('second')
  })

  it('caps loaded turns at MAX_TURNS_PER_SESSION', () => {
    const id = createSessionId()
    saveMeta({ sessionId: id, goal: 'g', cwd: '/tmp', startedAt: Date.now(), status: 'running' })
    for (let i = 0; i < MAX_TURNS_PER_SESSION + 50; i++) {
      appendTurn(id, { ts: i, user: `u${i}`, assistant: `a${i}`, status: 'completed' })
    }
    const loaded = loadTurns(id)
    expect(loaded.length).toBe(MAX_TURNS_PER_SESSION)
  })

  it('lists sessions sorted by startedAt desc', () => {
    const id1 = createSessionId()
    const id2 = createSessionId()
    saveMeta({ sessionId: id1, goal: 'old', cwd: '/tmp', startedAt: 1000, status: 'closed' })
    saveMeta({ sessionId: id2, goal: 'new', cwd: '/tmp', startedAt: 2000, status: 'running' })
    const list = listSessions()
    expect(list.map((s) => s.sessionId)).toEqual([id2, id1])
  })

  it('deletes session files', () => {
    const id = createSessionId()
    saveMeta({ sessionId: id, goal: 'g', cwd: '/tmp', startedAt: Date.now(), status: 'running' })
    appendTurn(id, { ts: 1, user: 'u', assistant: 'a', status: 'completed' })
    expect(deleteSession(id)).toBe(true)
    expect(loadMeta(id)).toBeNull()
    expect(loadTurns(id)).toEqual([])
  })

  it('computes session stats', () => {
    const id = createSessionId()
    saveMeta({ sessionId: id, goal: 'g', cwd: '/tmp', startedAt: 100, status: 'running' })
    appendTurn(id, { ts: 100, user: 'u1', assistant: 'a1', status: 'completed', tokens: { input: 50, output: 60 } })
    appendTurn(id, { ts: 200, user: 'u2', assistant: 'a2', status: 'completed', tokens: { input: 70, output: 80 } })
    const stats = getSessionStats(id)
    expect(stats?.turnCount).toBe(2)
    expect(stats?.totalTokens).toEqual({ input: 120, output: 140 })
    expect(stats?.oldestTurnAt).toBe(100)
    expect(stats?.newestTurnAt).toBe(200)
  })

  it('returns null stats for missing session', () => {
    expect(getSessionStats('does-not-exist')).toBeNull()
  })
})

import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { connect } from 'node:net'
import type { Socket } from 'node:net'
import { AcpWebSocketServer } from '../../src/integrations/acpWebSocket.js'
import type { ACPTransport } from '../../src/integrations/acpTransport.js'

const WS_GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11'
const ACCEPT_HASH_HEADER = (key: string): string =>
  Buffer.from(
    require('node:crypto').createHash('sha1').update(key + WS_GUID).digest('base64'),
  ).toString()

function buildHandshakeKey(): string {
  return Buffer.from(require('node:crypto').randomBytes(16)).toString('base64')
}

describe('AcpWebSocketServer', () => {
  let server: AcpWebSocketServer | undefined
  let port = 0
  const connectionPromises: Array<{ resolve: (t: ACPTransport) => void }> = []

  function setupConnectionCapture(): void {
    connectionPromises.length = 0
    server = new AcpWebSocketServer({
      port: 0,
      onConnection: (transport) => {
        const p = connectionPromises.shift()
        if (p) p.resolve(transport)
      },
    })
  }

  beforeEach(() => { setupConnectionCapture() })
  afterEach(async () => {
    if (server) await server.stop()
    server = undefined
  })

  it('accepts a valid WebSocket upgrade (handshake response includes correct Accept)', async () => {
    if (!server) throw new Error('server not initialized')
    const p = await server.start()
    port = p
    const key = buildHandshakeKey()
    const c = connect({ port, host: '127.0.0.1' }, () => {
      c.write([
        'GET /chat HTTP/1.1',
        'Host: 127.0.0.1',
        'Upgrade: websocket',
        'Connection: Upgrade',
        `Sec-WebSocket-Key: ${key}`,
        'Sec-WebSocket-Version: 13',
        '',
        '',
      ].join('\r\n'))
    })
    await new Promise<void>((resolve) => c.once('connect', () => resolve()))
    const response = await new Promise<string>((resolve) => {
      let buf = ''
      c.on('data', (chunk: Buffer) => {
        buf += chunk.toString('utf8')
        if (buf.includes('\r\n\r\n')) resolve(buf)
      })
      setTimeout(() => resolve(buf), 500)
    })
    expect(response).toContain('101 Switching Protocols')
    expect(response).toContain(`Sec-WebSocket-Accept: ${ACCEPT_HASH_HEADER(key)}`)
    c.end()
  })

  it('rejects non-websocket upgrade (returns 404)', async () => {
    if (!server) throw new Error('server not initialized')
    const p = await server.start()
    port = p
    const c = connect({ port, host: '127.0.0.1' }, () => {
      c.write('GET / HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n')
    })
    await new Promise<void>((resolve) => c.once('connect', () => resolve()))
    const response = await new Promise<string>((resolve) => {
      let buf = ''
      c.on('data', (chunk: Buffer) => {
        buf += chunk.toString('utf8')
      })
      c.on('end', () => resolve(buf))
      setTimeout(() => resolve(buf), 500)
    })
    expect(response).toContain('404')
    c.end()
  })

  it('rejects wrong version', async () => {
    if (!server) throw new Error('server not initialized')
    const p = await server.start()
    port = p
    const c = connect({ port, host: '127.0.0.1' }, () => {
      c.write([
        'GET /chat HTTP/1.1',
        'Host: 127.0.0.1',
        'Upgrade: websocket',
        'Connection: Upgrade',
        'Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==',
        'Sec-WebSocket-Version: 8',
        '',
        '',
      ].join('\r\n'))
    })
    await new Promise<void>((resolve) => c.once('connect', () => resolve()))
    const response = await new Promise<string>((resolve) => {
      let buf = ''
      c.on('data', (chunk: Buffer) => {
        buf += chunk.toString('utf8')
        if (buf.includes('\r\n\r\n')) resolve(buf)
      })
      setTimeout(() => resolve(buf), 200)
    })
    expect(response).toContain('426')
    c.end()
  })

  it('serves /health endpoint', async () => {
    if (!server) throw new Error('server not initialized')
    const p = await server.start()
    port = p
    const c = connect({ port, host: '127.0.0.1' }, () => {
      c.write('GET /health HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n')
    })
    await new Promise<void>((resolve) => c.once('connect', () => resolve()))
    const response = await new Promise<string>((resolve) => {
      let buf = ''
      c.on('data', (chunk: Buffer) => {
        buf += chunk.toString('utf8')
      })
      c.on('end', () => resolve(buf))
    })
    expect(response).toContain('200')
    expect(response).toContain('"ok":true')
    c.end()
  })
})

import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { McpHttpClient } from '../../src/core/mcpHttpClient.js'
import { storeToken } from '../../src/integrations/mcpOAuth.js'
import type { McpServerConfig } from '../../src/core/mcpClient.js'

function mockFetch(responses: Array<{ ok: boolean; status?: number; body: unknown }>): { calls: Array<{ url: string; headers: Record<string, string>; body: unknown }>; impl: typeof fetch } {
  const calls: Array<{ url: string; headers: Record<string, string>; body: unknown }> = []
  let i = 0
  const impl = (async (input: string | URL | Request, init?: RequestInit) => {
    calls.push({
      url: typeof input === 'string' ? input : input.toString(),
      headers: init?.headers as Record<string, string> ?? {},
      body: init?.body ? JSON.parse(init.body as string) : undefined,
    })
    const r = responses[i++] ?? responses[responses.length - 1]
    return new Response(
      typeof r.body === 'string' ? r.body : JSON.stringify(r.body),
      { status: r.status ?? (r.ok ? 200 : 400), headers: { 'content-type': 'application/json' } },
    )
  }) as typeof fetch
  return { calls, impl }
}

describe('McpHttpClient', () => {
  let dir: string
  const oldHome = process.env.HOME

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), 'mcp-http-'))
    process.env.HOME = dir
  })
  afterEach(() => {
    process.env.HOME = oldHome
    rmSync(dir, { recursive: true, force: true })
  })

  it('connects and lists tools', async () => {
    const { calls, impl } = mockFetch([
      { ok: true, body: { result: { tools: [{ name: 'foo', description: 'd', inputSchema: { type: 'object' } }] } } },
    ])
    const client = new McpHttpClient(
      { name: 'srv', type: 'http', url: 'https://mcp.example.com' },
      { fetchImpl: impl },
    )
    await client.connect()
    const tools = await client.listTools()
    expect(tools).toEqual([{ name: 'foo', description: 'd', inputSchema: { type: 'object' } }])
    expect(calls[0]?.url).toBe('https://mcp.example.com')
    expect(calls[0]?.body).toMatchObject({ method: 'tools/list' })
  })

  it('throws when connecting to non-http config', async () => {
    const { impl } = mockFetch([])
    const client = new McpHttpClient({ name: 'srv', type: 'stdio', command: ['x'] }, { fetchImpl: impl })
    await expect(client.connect()).rejects.toThrow(/non-http/)
  })

  it('attaches Authorization: Bearer from oauth token store', async () => {
    storeToken({
      serverId: 'auth-srv',
      accessToken: 'token-abc',
      acquiredAt: Date.now(),
      expiresAt: Date.now() + 3600_000,
    })
    const { calls, impl } = mockFetch([
      { ok: true, body: { result: { tools: [] } } },
    ])
