      engine: fakeEngine,
      cwd: tmpCwd,
    } as never

    const result = cmd!.handler('on', ctx) as { type: string; value: string }
    expect(result.type).toBe('text')
    expect(result.value).toContain('ON')

    const reloaded = loadSettings(tmpCwd)
    expect(reloaded.poor?.enabled).toBe(true)

