    }
    const cfg = {
      apiKey: 'k', model: 'model-a', maxIterations: 10,
      cwd: tmpProj, permissionMode: 'bypassPermissions',
      enabledModules: [], eventLog,
      provider: 'openai-compatible',
      models: {
